  console.log(`Detected platform: ${detectedPlatform.displayName}`);

  let defaultTier = 'aggressive';
  let maxTokenBudget: number | undefined = undefined;
  let showInlineSummary = true;
  let enableSemanticRanking = false;

  if (!isNonInteractive) {
    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout
    });

    const question = (query: string): Promise<string> => {
      return new Promise((resolve) => rl.question(query, resolve));
    };

    const defaultTierInput = await question("Select default compression tier (normal/medium/aggressive) [aggressive]: ");
    if (['normal', 'medium', 'aggressive'].includes(defaultTierInput.trim())) {
      defaultTier = defaultTierInput.trim();
    }

    const budgetInput = await question("Enter maximum token budget per call (number or press Enter for none) [none]: ");
    if (budgetInput.trim()) {
      maxTokenBudget = Number(budgetInput.trim());
    }

    const showSummaryInput = await question("Show inline token savings summary on file reads? (yes/no) [yes]: ");
    if (showSummaryInput.trim().toLowerCase() === 'no') {
      showInlineSummary = false;
    }

    const enableRankingInput = await question("Enable ONNX semantic embedding ranking? (yes/no) [no]: ");
    if (enableRankingInput.trim().toLowerCase() === 'yes') {
      enableSemanticRanking = true;
    }

    rl.close();
  }

  const configPath = path.resolve(workspaceRoot, '.shanaxon.json');
  const config = {
    defaultTier,
    ...(maxTokenBudget !== undefined ? { maxTokenBudget } : {}),
    showInlineSummary,
    enableSemanticRanking,
    activeModel: 'claude-3-7-sonnet',
    pricingModel: 'claude-sonnet-4',
    enableIntelligencePipeline: true,
    enableCapabilityEqualization: true,
    enableCriticalMemory: true,
    enableQualityGate: true,
    qualityGateMinRetention: 0.85,
    economics: {
      enabled: true,
      optimizerCostMode: 'estimated',
      optimizerCostPerSecond: 0.001,
      minimumSavingsUsd: 0.00001,
      minimumSavingsPercent: 2.0,
      qualityFloor: 0.85,
      trackRetries: true,
      enablePreflight: true
    },
    preserveCommentPatterns: ["TODO", "FIXME", "@api", "@public"],
    alwaysInclude: [],
    excludePatterns: projectInfo.excludePatterns,
    cacheStrategy: "disk",
    cachePath: ".shanaxon/cache.json",
    telemetryRotationLimit: 500
  };

  await fs.writeFile(configPath, JSON.stringify(config, null, 2), 'utf-8');
  console.log(`\n✓ Config file successfully created at: ${configPath}`);

  // Automatically write MCP configuration to detected platform JSON files
  console.log("\nConfiguring IDE / AI Platform MCP settings...");
  const mcpConfigResults = await autoConfigureMcp(workspaceRoot);
  for (const res of mcpConfigResults) {
    console.log(`✓ Shanaxon MCP server registered for ${res.platform}: ${res.configPath}`);
  }

  console.log("\n==================================================");
  console.log("MCP SERVER CONFIGURATION SNIPPET");
  console.log("==================================================");
  console.log("Manual fallback JSON snippet:");
  console.log(JSON.stringify({
    mcpServers: {
      "shanaxon": {
        "command": "npx",
        "args": ["-y", "shanaxon-mcp"]
      }
    }
  }, null, 2));
  console.log("==================================================");
}

if (require.main === module) {
  runInit().catch((err) => {
    console.error("Setup wizard failed:", err);
    process.exit(1);
  });
}

import * as path from 'path';
import { promises as fs } from 'fs';
import { WorkspaceIndexer } from './workspaceIndexer';
import { CodeCompressionEngine } from './parser';
import { estimateTokens } from './budgetManager';

async function runBenchmark() {
  const target = process.argv[2] || '.';
  const absoluteTarget = path.resolve(target);
  const workspaceRoot = process.cwd();

  console.log(`=== Shanaxon CLI Benchmark Tool ===`);
  console.log(`Target: ${absoluteTarget}`);

  const indexer = new WorkspaceIndexer(workspaceRoot);
  let files: string[] = [];
  try {
    files = await indexer.indexWorkspace(target);
  } catch (err: any) {
    console.error(`Error crawling workspace: ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log("No supported files found to index.");
    process.exit(0);
  }

  const engine = new CodeCompressionEngine();
  await engine.init();

  let totalRawTokens = 0;
  let totalCompTokens = 0;
  const startOverall = Date.now();

  console.log(`Processing ${files.length} files...`);

  for (const file of files) {
    try {
      const code = await fs.readFile(file, 'utf-8');
      const compressed = await engine.compress(code, file, 'aggressive');

      const rawTokens = estimateTokens(code);
      const compTokens = estimateTokens(compressed);

      totalRawTokens += rawTokens;
      totalCompTokens += compTokens;
    } catch (err: any) {
      console.error(`Error processing ${path.basename(file)}: ${err.message}`);
    }
  }

  const duration = Date.now() - startOverall;
  const saved = totalRawTokens - totalCompTokens;
  const pct = totalRawTokens > 0 ? ((saved / totalRawTokens) * 100).toFixed(1) : '0';
  const avgLatency = (duration / files.length).toFixed(1);

  console.log("\n==================================================");
  console.log("BENCHMARK REPORT SUMMARY");
  console.log("==================================================");
  console.log(`Total Files Indexed        : ${files.length}`);
  console.log(`Raw Cumulative Tokens      : ${totalRawTokens.toLocaleString()}`);
  console.log(`Compressed Output Tokens   : ${totalCompTokens.toLocaleString()}`);
  console.log(`Context Tokens Reclaimed   : ${saved.toLocaleString()} Saved`);
  console.log(`Overall Compression Ratio  : ${pct}% reduction`);
  console.log(`Total Duration             : ${duration}ms`);
  console.log(`Average Latency            : ${avgLatency}ms per file`);
  console.log("==================================================");
}

runBenchmark().catch((err) => {
  console.error("Benchmark failed:", err);
  process.exit(1);
});

import * as path from 'path';
import { promises as fs } from 'fs';
import { CodeCompressionEngine } from './parser';
import { WorkspaceIndexer } from './workspaceIndexer';
import { Tokenizer } from './tokenizer';

export interface BenchmarkStats {
  tier: string;
  totalFiles: number;
  rawChars: number;
  compressedChars: number;
  rawTokens: number;
  compressedTokens: number;
  savingsPct: number;
  totalTimeMs: number;
  avgLatencyMs: number;
}

/**
 * Real Codebase Benchmark Suite.
 * Benchmarks Shanaxon AST compression against actual workspace repository files.
 */
export async function runRealBenchmark(workspaceRoot: string): Promise<BenchmarkStats[]> {
  const engine = new CodeCompressionEngine();
  await engine.init();

  const indexer = new WorkspaceIndexer(workspaceRoot);
  const matchedFiles = await indexer.indexWorkspace('src');

  const fileContents: { filePath: string; code: string }[] = [];
  for (const file of matchedFiles) {
    try {
      const code = await fs.readFile(file, 'utf-8');
      fileContents.push({ filePath: file, code });
    } catch {}
  }

  const tiers: ('normal' | 'medium' | 'aggressive')[] = ['normal', 'medium', 'aggressive'];
  const results: BenchmarkStats[] = [];

  for (const tier of tiers) {
    const startTime = Date.now();
    let rawChars = 0;
    let compressedChars = 0;
    let rawTokens = 0;
    let compressedTokens = 0;

    for (const f of fileContents) {
      rawChars += f.code.length;
      rawTokens += Tokenizer.countTokens(f.code, f.filePath);

      const compressed = await engine.compress(f.code, f.filePath, tier);
      compressedChars += compressed.length;
      compressedTokens += Tokenizer.countTokens(compressed, f.filePath);
    }

    const totalTimeMs = Date.now() - startTime;
    const savingsPct = rawTokens > 0 ? ((rawTokens - compressedTokens) / rawTokens) * 100 : 0;

    results.push({
      tier,
      totalFiles: fileContents.length,
      rawChars,
      compressedChars,
      rawTokens,
      compressedTokens,
      savingsPct: Math.round(savingsPct * 100) / 100,
      totalTimeMs,
      avgLatencyMs: Math.round((totalTimeMs / (fileContents.length || 1)) * 100) / 100
    });
  }

  return results;
}

export async function runBenchmarkCli(workspaceRoot = process.cwd()): Promise<void> {
  console.log("===========================================================");
  console.log("SHANAXON REAL CODEBASE COMPRESSION BENCHMARK");
  console.log("===========================================================");

  console.log(`Repository Root: ${workspaceRoot}`);

  const results = await runRealBenchmark(workspaceRoot);

  for (const res of results) {
    console.log(`\nTier: ${res.tier.toUpperCase()}`);
    console.log(` - Total Files Processed: ${res.totalFiles}`);
    console.log(` - Raw Code Volume     : ${res.rawChars.toLocaleString()} chars (~${res.rawTokens.toLocaleString()} BPE tokens)`);
    console.log(` - Compressed Volume   : ${res.compressedChars.toLocaleString()} chars (~${res.compressedTokens.toLocaleString()} BPE tokens)`);
    console.log(` - Token Reduction     : ${res.savingsPct}% tokens saved`);
    console.log(` - Total Execution Time: ${res.totalTimeMs}ms (${res.avgLatencyMs}ms/file)`);

    const rawCost = (res.rawTokens / 1000000) * 3.00;
    const compressedCost = (res.compressedTokens / 1000000) * 3.00;
    const savedDollar = rawCost - compressedCost;
    console.log(` - Projected Cost (Claude Sonnet @ $3/1M): $${rawCost.toFixed(4)} → $${compressedCost.toFixed(4)} (Saved $${savedDollar.toFixed(4)}/call)`);
  }

  console.log("\n===========================================================");
  console.log("BENCHMARK COMPLETED SUCCESSFULLY!");
  console.log("===========================================================");
}

if (require.main === module) {
  runBenchmarkCli().catch(err => {
    console.error("Benchmark failed:", err);
    process.exit(1);
  });
}

import { CodeCompressionEngine } from './parser';
