/**
 * Estimates BPE tokens using language-aware Tokenizer.
 */
export function estimateTokens(text: string, filePath?: string): number {
  return Tokenizer.countTokens(text, filePath);
}

/**
 * Greedily allocates compression tiers to files to stay within maxTokenBudget,
 * respecting optional ModelPolicy tier caps and QualityGate retention thresholds.
 */
export async function enforceBudget(
  files: FileInput[],
  engine: CodeCompressionEngine,
  maxTokenBudget: number,
  importanceScores?: Map<string, number>,
  options?: BudgetEnforceOptions
): Promise<{ results: BudgetResult[]; budgetExceeded: boolean }> {
  const results: BudgetResult[] = [];
  const blockedTiers = new Map<string, Set<CompressionTier>>();

  const isTierAllowed = (filePath: string, candidateTier: 'normal' | 'medium' | 'aggressive'): boolean => {
    if (blockedTiers.get(filePath)?.has(candidateTier)) {
      return false;
    }
    if (options?.activeModel) {
      const adjusted = adjustTierForModel(candidateTier, options.activeModel);
      if (adjusted !== candidateTier) {
        return false;
      }
    }
    return true;
  };

  const passesQuality = (rawCode: string, compressedCode: string, candidateTier: 'normal' | 'medium' | 'aggressive'): boolean => {
    if (options?.enableQualityGate === false || !options?.taskProfile) {
      return true;
    }
    const qg = evaluateQualityGate(
      rawCode,
      compressedCode,
      options.taskProfile,
      candidateTier,
      options.qualityGateMinRetention
    );
    return qg.passed;
  };

  for (const file of files) {
    const initialTier = options?.initialTiers?.get(file.filePath);
    if (initialTier === 'omitted') {
      const omittedText = `[Omitted by Shanaxon Context Intelligence Engine]`;
      results.push({
        filePath: file.filePath,
        content: omittedText,
        tier: 'omitted',
        estimatedTokens: estimateTokens(omittedText, file.filePath)
      });
      continue;
    }

    let startTier: 'normal' | 'medium' | 'aggressive' =
      initialTier === 'medium' || initialTier === 'aggressive' ? initialTier : 'normal';
    if (options?.activeModel && startTier !== 'normal') {
      const adjusted = adjustTierForModel(startTier, options.activeModel);
      startTier = adjusted === 'omitted' ? 'normal' : adjusted;
    }

    let content = await engine.compress(file.code, file.filePath, startTier);
    if (startTier !== 'normal' && !passesQuality(file.code, content, startTier)) {
      startTier = 'normal';
      content = await engine.compress(file.code, file.filePath, 'normal');
    }

    const tokens = estimateTokens(content, file.filePath);
    results.push({
      filePath: file.filePath,
      content,
      tier: startTier,
      estimatedTokens: tokens
    });
  }

  let totalTokens = results.reduce((sum, r) => sum + r.estimatedTokens, 0);
  if (totalTokens <= maxTokenBudget) {
    return { results, budgetExceeded: false };
  }

  // 1. Escalate to Medium (Greedily escalate largest normal file to medium)
  while (totalTokens > maxTokenBudget) {
    const normalFiles = results.filter((r) => r.tier === 'normal' && isTierAllowed(r.filePath, 'medium'));
    if (normalFiles.length === 0) break;

    normalFiles.sort((a, b) => b.estimatedTokens - a.estimatedTokens);
    const target = normalFiles[0];

    const fileInput = files.find((f) => f.filePath === target.filePath)!;
    const mediumContent = await engine.compress(fileInput.code, fileInput.filePath, 'medium');

    if (!passesQuality(fileInput.code, mediumContent, 'medium')) {
      const set = blockedTiers.get(target.filePath) || new Set<CompressionTier>();
      set.add('medium');
      blockedTiers.set(target.filePath, set);
      continue;
    }

    const newTokens = estimateTokens(mediumContent, fileInput.filePath);
    target.content = mediumContent;
    target.tier = 'medium';
    target.estimatedTokens = newTokens;

    totalTokens = results.reduce((sum, r) => sum + r.estimatedTokens, 0);
  }

  if (totalTokens <= maxTokenBudget) {
    return { results, budgetExceeded: false };
  }

  // 2. Escalate to Aggressive (Greedily escalate largest medium file to aggressive)
  while (totalTokens > maxTokenBudget) {
    const mediumFiles = results.filter((r) => r.tier === 'medium' && isTierAllowed(r.filePath, 'aggressive'));
    if (mediumFiles.length === 0) break;

    mediumFiles.sort((a, b) => b.estimatedTokens - a.estimatedTokens);
    const target = mediumFiles[0];

    const fileInput = files.find((f) => f.filePath === target.filePath)!;
    const aggressiveContent = await engine.compress(fileInput.code, fileInput.filePath, 'aggressive');

    if (!passesQuality(fileInput.code, aggressiveContent, 'aggressive')) {
      const set = blockedTiers.get(target.filePath) || new Set<CompressionTier>();
      set.add('aggressive');
      blockedTiers.set(target.filePath, set);
      continue;
    }

    const newTokens = estimateTokens(aggressiveContent, fileInput.filePath);
    target.content = aggressiveContent;
    target.tier = 'aggressive';
    target.estimatedTokens = newTokens;

    totalTokens = results.reduce((sum, r) => sum + r.estimatedTokens, 0);
  }

  if (totalTokens <= maxTokenBudget) {
    return { results, budgetExceeded: false };
  }

  // 3. Drop files (Omit lowest importance / highest token impact files first)
  // Sort candidates by importance ascending (lowest PageRank score dropped first),
  // then by estimatedTokens descending (largest token hog dropped first).
  const dropCandidates = results
    .filter(r => r.tier !== 'omitted')
    .sort((a, b) => {
      const importanceA = importanceScores?.get(a.filePath) ?? 0.5;
      const importanceB = importanceScores?.get(b.filePath) ?? 0.5;
      if (importanceA !== importanceB) {
        return importanceA - importanceB; // Lowest importance first
      }
      return b.estimatedTokens - a.estimatedTokens; // Highest token count first
    });

  for (const fileToOmit of dropCandidates) {
    if (totalTokens <= maxTokenBudget) {
      break;
    }

    const target = results.find(r => r.filePath === fileToOmit.filePath)!;
    totalTokens -= target.estimatedTokens;
    target.content = `[File "${target.filePath}" omitted to stay within token budget]`;
    target.tier = 'omitted';
    target.estimatedTokens = estimateTokens(target.content, target.filePath);
    totalTokens += target.estimatedTokens;
  }

  return {
    results,
    budgetExceeded: totalTokens > maxTokenBudget
  };
}

import { promises as fs } from 'fs';
import * as path from 'path';
import { computeContentHash } from './hashCache';
import { resolveTenantContext, scopedKey } from '../security/tenantIsolation';
import { getConfig } from './configLoader';

export interface CacheValue {
  normal: string;
  medium: string;
  aggressive: string;
  mtimeMs: number;
  hash?: string;
}

export class AstCache {
  private cache = new Map<string, CacheValue>();
  private maxEntries: number;
  private cacheDiskPath: string;
  private flushTimeout: NodeJS.Timeout | null = null;

  constructor(maxEntries = 200, cacheDiskPath = '.shanaxon/cache.json') {
    this.maxEntries = maxEntries;
    this.cacheDiskPath = path.resolve(cacheDiskPath);
  }

  /**
   * Loads cached results from disk.
   */
  async loadFromDisk(): Promise<void> {
    try {
      const data = await fs.readFile(this.cacheDiskPath, 'utf-8');
      const parsed = JSON.parse(data);
      this.cache.clear();

      for (const [key, value] of Object.entries(parsed)) {
        const val = value as CacheValue;
        this.cache.set(path.resolve(key), val);
      }
    } catch {
      // Fail silently if cache file is missing or invalid
    }
  }

  /**
   * Serializes and writes cache map to disk.
   */
  async flushToDisk(): Promise<void> {
    try {
      const dir = path.dirname(this.cacheDiskPath);
      await fs.mkdir(dir, { recursive: true });

      const obj: Record<string, CacheValue> = {};
      for (const [key, val] of this.cache.entries()) {
        obj[key] = val;
      }

      const tempPath = `${this.cacheDiskPath}.${Date.now()}.${Math.random().toString(36).substring(2, 7)}.tmp`;
      await fs.writeFile(tempPath, JSON.stringify(obj, null, 2), 'utf-8');
      await fs.rename(tempPath, this.cacheDiskPath);
    } catch (err) {
      console.error('Failed to flush AST cache to disk:', err);
    }
  }

  private scheduleFlush() {
    if (this.flushTimeout) return;
    this.flushTimeout = setTimeout(async () => {
      this.flushTimeout = null;
      await this.flushToDisk();
    }, 2000); // 2 second debounce is highly optimal
  }

  /**
   * Clears in-memory and disk cache.
   */
  async clear(): Promise<void> {
    this.cache.clear();
    await this.flushToDisk();
  }

  /**
   * Gets cached compression tier if file content hash or modification time has not changed.
   */
  async get(filePath: string, tier: 'normal' | 'medium' | 'aggressive', currentCodeContent?: string): Promise<string | null> {
    const absPath = path.resolve(filePath);
    const tenant = resolveTenantContext(getConfig());
    const cacheKey = scopedKey(absPath, tenant);
    const entry = this.cache.get(cacheKey);
    if (!entry) return null;

    try {
      if (currentCodeContent !== undefined && entry.hash) {
        const currentHash = computeContentHash(currentCodeContent);
        if (currentHash !== entry.hash) {
          this.cache.delete(cacheKey);
          this.scheduleFlush();
          return null;
        }
      } else {
        const stat = await fs.stat(absPath);
        if (stat.mtimeMs !== entry.mtimeMs) {
          this.cache.delete(cacheKey);
          this.scheduleFlush();
          return null;
        }
      }

      // LRU refresh: reinsert
      this.cache.delete(cacheKey);
      this.cache.set(cacheKey, entry);

      return entry[tier];
    } catch {
      this.cache.delete(cacheKey);
      this.scheduleFlush();
      return null;
    }
  }

  /**
   * Updates cached compression tiers and triggers debounced flush.
   */
  async set(filePath: string, values: { normal: string; medium: string; aggressive: string }, codeContent?: string): Promise<void> {
    const absPath = path.resolve(filePath);
    const tenant = resolveTenantContext(getConfig());
    const cacheKey = scopedKey(absPath, tenant);
    try {
      const stat = await fs.stat(absPath).catch(() => ({ mtimeMs: Date.now() }));
      const hash = codeContent ? computeContentHash(codeContent) : undefined;

      if (this.cache.size >= this.maxEntries) {
        const oldestKey = this.cache.keys().next().value;
        if (oldestKey) {
          this.cache.delete(oldestKey);
        }
      }

      this.cache.set(cacheKey, {
        ...values,
        mtimeMs: stat.mtimeMs,
        hash
      });

      this.scheduleFlush();
    } catch {
      // Ignore failures
    }
  }
}

export interface AlignResult {
  stablePrefix: string;
  dynamicSuffix: string;
  dynamicCount: number;
  estimatedCacheSavings: string;
}

/**
 * Cache-Aligned Prompt Stabilizer.
 * Reorganizes system prompts and context by relocating volatile dynamic values
 * (timestamps, UUIDs, random hashes, process IDs, timestamps) into a suffix block.
 * Allows Anthropic and OpenAI KV Caching to hit >90% prefix cache rates.
 */
export class CacheAligner {
  /**
   * Main entry point: stabilizes prompt text by separating static prefix from dynamic values.
   */
  align(prompt: string): AlignResult {
    let stablePrefix = prompt;
    const dynamicValues: { original: string; placeholder: string }[] = [];

    // 1. ISO Timestamps (e.g. 2026-08-01T05:22:40Z or 2026-08-01 05:22:40)
    const isoTimestampRegex = /\b\d{4}-\d{2}-\d{2}[T\s]\d{2}:\d{2}:\d{2}(?:\.\d+)?(?:Z|[+-]\d{2}:?\d{2})?\b/g;
    stablePrefix = stablePrefix.replace(isoTimestampRegex, (match) => {
      const placeholder = `{{DYN_TIMESTAMP_${dynamicValues.length + 1}}}`;
      dynamicValues.push({ original: match, placeholder });
      return placeholder;
    });

    // 2. UUIDs (e.g. 465c4a12-27fc-4bab-821d-4b8bbd3f2f79)
    const uuidRegex = /\b[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\b/g;
    stablePrefix = stablePrefix.replace(uuidRegex, (match) => {
      const placeholder = `{{DYN_UUID_${dynamicValues.length + 1}}}`;
      dynamicValues.push({ original: match, placeholder });
      return placeholder;
    });

    // 3. Process IDs / Hex hashes (e.g. ProcessId: 14968, sha256 64-hex, commit hashes 40-hex)
    const shaHexRegex = /\b[0-9a-fA-F]{40,64}\b/g;
    stablePrefix = stablePrefix.replace(shaHexRegex, (match) => {
      const placeholder = `{{DYN_HASH_${dynamicValues.length + 1}}}`;
      dynamicValues.push({ original: match, placeholder });
      return placeholder;
    });

    // 4. Dynamic Process ID / Port assignments
    const pidRegex = /\b(?:PID|ProcessId|port):\s*\d+\b/gi;
    stablePrefix = stablePrefix.replace(pidRegex, (match) => {
      const placeholder = `{{DYN_ENV_${dynamicValues.length + 1}}}`;
      dynamicValues.push({ original: match, placeholder });
      return placeholder;
    });

    const dynamicCount = dynamicValues.length;
    let dynamicSuffix = '';

    if (dynamicCount > 0) {
      dynamicSuffix = dynamicValues
        .map((item) => `${item.placeholder} = "${item.original}"`)
        .join('\n');
    }

    const estimatedCacheSavings =
      dynamicCount > 0
        ? `~90% KV Cache discount on ${Math.round((stablePrefix.length / (prompt.length || 1)) * 100)}% of prompt prefix`
        : '0% (No dynamic variables detected)';

    return {
      stablePrefix,
      dynamicSuffix,
      dynamicCount,
      estimatedCacheSavings,
    };
  }
}

import * as path from 'path';
