import { execFile } from 'child_process';
import * as path from 'path';
import * as fs from 'fs';

/**
 * Returns only the changed git hunks of a file (with configurable context lines)
 * rather than sending the full file. Safe against missing git CLI binaries & non-git directories.
 */
export function getFileDiffContext(
  filePath: string,
  workspaceRoot: string,
  contextLines = 10
): Promise<string> {
  return new Promise((resolve) => {
    const absPath = path.resolve(filePath);
    const relPath = path.relative(workspaceRoot, absPath).replace(/\\/g, '/');

    const gitDir = path.join(workspaceRoot, '.git');
    if (!fs.existsSync(gitDir)) {
      resolve(`[Shanaxon Diff Mode] Git repository uninitialized in workspace.`);
      return;
    }

    const safeContextLines = Math.max(0, Math.floor(Number(contextLines) || 10));
    const args = ['diff', `-U${safeContextLines}`, '--', relPath];

    execFile('git', args, { cwd: workspaceRoot }, (err, stdout) => {
      if (err) {
        if ((err as any).code === 'ENOENT') {
          resolve(`[Shanaxon Diff Mode] Git executable not found on system PATH.`);
        } else {
          resolve(`[Shanaxon Diff Mode] No uncommitted changes detected for: ${relPath}`);
        }
      } else if (!stdout || !stdout.trim()) {
        resolve(`[Shanaxon Diff Mode] No uncommitted changes detected for: ${relPath}`);
      } else {
        resolve(stdout.trim());
      }
    });
  });
}

// @ts-ignore
import { pipeline } from '@xenova/transformers';
import { promises as fs } from 'fs';
import * as path from 'path';
import { computeContentHash } from './hashCache';

export interface PersistedEmbedding {
  hash: string;
  vector: number[];
}

export class EmbeddingRanker {
  private extractor: any = null;
  private isInitialized = false;
  private isAvailable = true;
  private embeddings = new Map<string, number[]>();
  private contentHashes = new Map<string, string>();
  private diskPath: string;
  private saveTimeout: NodeJS.Timeout | null = null;

  constructor(workspaceRoot = process.cwd()) {
    this.diskPath = path.resolve(workspaceRoot, '.shanaxon/embeddings.json');
  }

  /**
   * Initializes the ONNX model pipeline lazily and loads cached embeddings from disk.
   */
  async init() {
    if (this.isInitialized) return;

    await this.loadFromDisk();

    try {
      // Load local ONNX sentence transformer (all-MiniLM-L6-v2)
      try {
        this.extractor = await pipeline('feature-extraction', 'Xenova/all-MiniLM-L6-v2');
      } catch {
        this.extractor = await pipeline('embeddings', 'Xenova/all-MiniLM-L6-v2');
      }
      this.isAvailable = true;
    } catch (err) {
      console.warn("Shanaxon EmbeddingRanker warning: ONNX model loading failed. Semantic ranking falls back to default sorting.", err);
      this.isAvailable = false;
    } finally {
      this.isInitialized = true;
    }
  }

  /**
   * Loads cached embeddings and hashes from disk.
   */
  async loadFromDisk() {
    try {
      const data = await fs.readFile(this.diskPath, 'utf-8');
      const parsed: Record<string, PersistedEmbedding> = JSON.parse(data);
      this.embeddings.clear();
      this.contentHashes.clear();

      for (const [filePath, entry] of Object.entries(parsed)) {
        const absPath = path.resolve(filePath);
        this.embeddings.set(absPath, entry.vector);
        this.contentHashes.set(absPath, entry.hash);
      }
    } catch {
      // Ignore missing or corrupted cache
    }
  }

  /**
   * Serializes and writes embeddings to disk atomically using temporary file rename.
   */
  async flushToDisk(): Promise<void> {
    try {
      const dir = path.dirname(this.diskPath);
      await fs.mkdir(dir, { recursive: true });

      const obj: Record<string, PersistedEmbedding> = {};
      for (const [key, vector] of this.embeddings.entries()) {
        const hash = this.contentHashes.get(key) || '';
        obj[key] = { hash, vector };
      }

      const tempPath = `${this.diskPath}.${Date.now()}.${Math.random().toString(36).substring(2, 7)}.tmp`;
      await fs.writeFile(tempPath, JSON.stringify(obj), 'utf-8');
      await fs.rename(tempPath, this.diskPath);
    } catch (err) {
      console.error('Failed to flush embeddings to disk:', err);
    }
  }

  private scheduleSave() {
    if (this.saveTimeout) return;
    this.saveTimeout = setTimeout(async () => {
      this.saveTimeout = null;
      await this.flushToDisk();
    }, 2000);
  }

  /**
   * Clears the in-memory index and disk store.
   */
  async clear() {
    this.embeddings.clear();
    this.contentHashes.clear();
    await this.flushToDisk();
  }

  /**
   * Generates a 384-dimensional normalized embedding vector for the text.
   */
  async getEmbedding(text: string): Promise<number[]> {
    if (!this.isInitialized) {
      await this.init();
    }

    if (!this.isAvailable || !this.extractor) {
      return [];
    }

    try {
      const output = await this.extractor(text, { pooling: 'mean', normalize: true });
      return Array.from(output.data);
    } catch {
      return [];
    }
  }

  /**
   * Embeds and indexes a file signature. Skips inference if content hash matches cached entry.
   */
  async indexFile(filePath: string, text: string) {
    if (!this.isInitialized) {
      await this.init();
    }

    const absPath = path.resolve(filePath);
    const hash = computeContentHash(text);

    // Skip inference if hash matches cached embedding
    if (this.contentHashes.get(absPath) === hash && this.embeddings.has(absPath)) {
      return;
    }

    if (!this.isAvailable) {
      // Fallback mode when model is offline or unavailable
      this.contentHashes.set(absPath, hash);
      this.embeddings.set(absPath, [1.0, 0.0, 0.0]);
      this.scheduleSave();
      return;
    }

    try {
      const vector = await this.getEmbedding(text);
      if (vector.length > 0) {
        this.embeddings.set(absPath, vector);
        this.contentHashes.set(absPath, hash);
        this.scheduleSave();
      }
    } catch (err) {
      console.error(`Failed to generate embedding for ${filePath}:`, err);
    }
  }

  /**
   * Ranks all indexed files by cosine similarity to the query string.
   */
  async rankFiles(query: string, topK = 5): Promise<{ filePath: string; score: number }[]> {
    if (!this.isInitialized) {
      await this.init();
    }
    if (!this.isAvailable || this.embeddings.size === 0) {
      return [];
    }

    const queryVector = await this.getEmbedding(query);
    if (queryVector.length === 0) return [];

    const results: { filePath: string; score: number }[] = [];

    for (const [filePath, fileVector] of this.embeddings.entries()) {
      const score = cosineSimilarity(queryVector, fileVector);
      results.push({ filePath, score });
    }

    results.sort((a, b) => b.score - a.score);
    return results.slice(0, topK);
  }
}

/**
 * Computes cosine similarity between two vectors.
 */
function cosineSimilarity(vecA: number[], vecB: number[]): number {
  if (vecA.length === 0 || vecB.length === 0) return 0;
  let dotProduct = 0.0;
  let normA = 0.0;
  let normB = 0.0;
  for (let i = 0; i < vecA.length; i++) {
    dotProduct += vecA[i] * vecB[i];
    normA += vecA[i] * vecA[i];
    normB += vecB[i] * vecB[i];
  }
  if (normA === 0 || normB === 0) return 0;
  return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
}

import { exec } from 'child_process';
import * as path from 'path';

function runGitCommand(cmd: string, cwd: string): Promise<string> {
  return new Promise((resolve) => {
    exec(cmd, { cwd }, (err, stdout) => {
      if (err) {
        resolve('');
      } else {
        resolve(stdout.trim());
      }
    });
  });
}

/**
 * Dynamically resolves file tier based on modification history.
 * - Recently modified/uncommitted files get full detail (normal).
 * - Untouched files (> 30 days) get optimized detail (aggressive).
 */
export async function getGitAwareTier(
  filePath: string,
  workspaceRoot: string,
  defaultTier: 'normal' | 'medium' | 'aggressive'
): Promise<'normal' | 'medium' | 'aggressive'> {
  try {
    const absPath = path.resolve(filePath);
    const relPath = path.relative(workspaceRoot, absPath).replace(/\\/g, '/');

    // 1. Check if uncommitted, modified, or staged
    const statusOutput = await runGitCommand(`git status --porcelain "${relPath}"`, workspaceRoot);
    if (statusOutput.length > 0) {
      return 'normal';
    }

    // 2. Check if modified in last 24 hours
    const last24hLog = await runGitCommand(`git log --since="24 hours ago" --name-only --format=format: -- "${relPath}"`, workspaceRoot);
    if (last24hLog.length > 0) {
      return 'normal';
    }

    // 3. Check if modified in last 30 days
    const last30dLog = await runGitCommand(`git log --since="30 days ago" --name-only --format=format: -- "${relPath}"`, workspaceRoot);
    if (last30dLog.length === 0) {
      // Confirm file is tracked to avoid categorizing new files as aggressive
      const isTracked = await runGitCommand(`git ls-files "${relPath}"`, workspaceRoot);
      if (isTracked.length > 0) {
        return 'aggressive';
      }
    }
  } catch {
    // Fail silently using fallback
  }

  return defaultTier;
}

import * as path from 'path';
import { promises as fs } from 'fs';

const SENSITIVE_EXACT_NAMES = new Set([
  '.env',
  'id_rsa',
  'id_ed25519',
]);

const SENSITIVE_EXTENSIONS = new Set([
  '.pem',
  '.key',
  '.p12',
  '.pfx',
]);

/**
 * Normalizes a raw path string, resolving redundant segments and
 * standardizing on system-native separators (slashes or backslashes).
 */
export function normalizePath(rawPath: string): string {
  if (!rawPath) return '';
  return path.normalize(rawPath);
}

/**
 * Checks whether a path targets a sensitive file or credential artifact
 * (.env, .env.*, *.pem, *.key, *.p12, *.pfx, id_rsa, id_ed25519, *secret*, *credential*).
 */
export function isSensitiveFile(targetPath: string): boolean {
  if (!targetPath) return false;
  const normalized = targetPath.replace(/\\/g, '/');
  const segments = normalized.split('/').filter(Boolean);
  const baseName = path.basename(normalized).toLowerCase();

  if (
    SENSITIVE_EXACT_NAMES.has(baseName) ||
    baseName.startsWith('.env.') ||
    baseName.startsWith('id_rsa.') ||
    baseName.startsWith('id_ed25519.')
  ) {
    return true;
  }

  const ext = path.extname(baseName);
  if (SENSITIVE_EXTENSIONS.has(ext)) {
    return true;
  }

  for (const seg of segments) {
    const lower = seg.toLowerCase();
    if (lower.includes('secret') || lower.includes('credential')) {
      return true;
    }
  }

  return false;
}

function isContainedInBase(resolvedBase: string, resolvedTarget: string): boolean {
  const relative = path.relative(resolvedBase, resolvedTarget);
  // Empty string means identical paths (valid directory match)
  return !relative.startsWith('..') && !path.isAbsolute(relative);
}

/**
 * Validates a target path. Ensures:
 * 1. The target path is not a sensitive/secret file.
 * 2. The target path resides within the base directory (lexical + symlink realpath containment).
 * 3. The path exists and is readable using language-level fs abstractions.
 *
 * @param targetPath Path to validate.
 * @param baseDir Base directory boundary (defaults to process.cwd() or current workspace root).
 */
export async function validatePath(targetPath: string, baseDir?: string): Promise<boolean> {
  try {
    const resolvedTarget = path.resolve(targetPath);
    const resolvedBase = path.resolve(baseDir || process.cwd());

    if (isSensitiveFile(resolvedTarget)) {
      return false;
    }

    // 1. Lexical Directory Traversal Guardrail
    if (!isContainedInBase(resolvedBase, resolvedTarget)) {
      return false;
    }

    // 2. Local Permission / Existence Check using fs.promises.stat & access
    await fs.stat(resolvedTarget);
    await fs.access(resolvedTarget, fs.constants.R_OK);

    // 3. Symlink Containment Check via fs.realpath
    const realBase = await fs.realpath(resolvedBase);
    const realTarget = await fs.realpath(resolvedTarget);
    if (!isContainedInBase(realBase, realTarget)) {
      return false;
    }

    return true;
  } catch {
    return false;
  }
}

import * as crypto from 'crypto';

export interface HashCacheEntry {
  hash: string;
  normal: string;
  medium: string;
  aggressive: string;
  lastAccessed: number;
}

/**
 * SHA-256 cryptographic content-hash utility for rock-solid cache validation.
 */
export function computeContentHash(content: string): string {
  return crypto.createHash('sha256').update(content, 'utf-8').digest('hex');
}

export interface RankedFileScore {
  filePath: string;
  hybridScore: number;
  semanticScore: number;
  bm25Score: number;
}

/**
 * BM25 Keyword Search + Vector Cosine Similarity Hybrid Search Ranker.
 * Merges exact keyword/symbol matches with semantic conceptual embeddings.
 */
export class HybridRanker {
  private k1 = 1.5;
  private b = 0.75;

  /**
   * Computes BM25 score for a query against a document string.
   */
  public calculateBM25(query: string, documentText: string, avgDocLength = 500): number {
    if (!query || !documentText) return 0;

    const queryTerms = query.toLowerCase().match(/[a-zA-Z_0-9]+/g) || [];
    const docTerms = documentText.toLowerCase().match(/[a-zA-Z_0-9]+/g) || [];

    if (queryTerms.length === 0 || docTerms.length === 0) return 0;

    const docLength = docTerms.length;
    const termFreqs = new Map<string, number>();

    for (const term of docTerms) {
      termFreqs.set(term, (termFreqs.get(term) || 0) + 1);
    }

    let score = 0;

    for (const qTerm of queryTerms) {
      const freq = termFreqs.get(qTerm) || 0;
      if (freq > 0) {
        // IDF approximation factor for code search
        const idf = Math.log(1 + 10 / (1 + (termFreqs.has(qTerm) ? 1 : 0)));
        const numerator = freq * (this.k1 + 1);
        const denominator = freq + this.k1 * (1 - this.b + this.b * (docLength / avgDocLength));
        score += idf * (numerator / denominator);
      }
    }

    // Normalize BM25 score to [0.0, 1.0] range
    return Math.min(1.0, score / 10.0);
  }

  /**
   * Merges semantic scores and BM25 scores into unified hybrid scores.
   * Formula: 0.6 * semantic + 0.4 * BM25
   */
  public mergeHybridScores(
    semanticResults: { filePath: string; score: number }[],
    fileContentsMap: Map<string, string>,
    query: string
  ): RankedFileScore[] {
    const results: RankedFileScore[] = [];

    // Calculate average doc length across file contents
    let totalLen = 0;
    for (const [, text] of fileContentsMap.entries()) {
      totalLen += text.length;
    }
    const avgLen = fileContentsMap.size > 0 ? totalLen / fileContentsMap.size : 500;

    for (const item of semanticResults) {
      const content = fileContentsMap.get(item.filePath) || '';
      const bm25 = this.calculateBM25(query, content, avgLen);
      const semantic = Math.max(0, item.score);
      const hybrid = Math.round((0.6 * semantic + 0.4 * bm25) * 10000) / 10000;

      results.push({
        filePath: item.filePath,
        hybridScore: hybrid,
        semanticScore: Math.round(semantic * 10000) / 10000,
        bm25Score: Math.round(bm25 * 10000) / 10000
      });
    }

    // Sort descending by hybrid score
    results.sort((a, b) => b.hybridScore - a.hybridScore);
    return results;
  }
}

import * as path from 'path';
import { ImportGraph } from './importGraph';

export interface ImportanceScore {
  filePath: string;
  score: number; // PageRank score normalized [0.0, 1.0]
  recommendedTier: 'normal' | 'medium' | 'aggressive';
}

/**
 * Calculates PageRank-style centrality scores for files based on the import dependency graph.
 * High-centrality files (imported by many central components) are recommended for lower compression tiers.
 */
export class ImportanceScorer {
  /**
   * Runs PageRank power iteration over the import graph.
   * @param graph The workspace ImportGraph instance
   * @param dampingFactor PageRank damping factor (default: 0.85)
   * @param maxIterations Number of iterations (default: 20)
   */
  public calculatePageRank(
    graph: ImportGraph,
    dampingFactor = 0.85,
    maxIterations = 20
  ): Map<string, ImportanceScore> {
    const nodes = Array.from(graph.getAllNodes());
    const N = nodes.length;
    const scoresMap = new Map<string, ImportanceScore>();

    if (N === 0) {
      return scoresMap;
    }

    // Initial uniform probability distribution
    let rank = new Map<string, number>();
    for (const node of nodes) {
      rank.set(node, 1.0 / N);
    }

    const outEdgesMap = graph.getOutEdgesMap();

    // Power iteration
    for (let iter = 0; iter < maxIterations; iter++) {
      const newRank = new Map<string, number>();
      const teleport = (1.0 - dampingFactor) / N;

      for (const node of nodes) {
        newRank.set(node, teleport);
      }

      for (const u of nodes) {
        const currentRank = rank.get(u) || 0;
        const targets = outEdgesMap.get(u);
        const outDegree = targets ? targets.size : 0;

        if (outDegree > 0) {
          const share = (dampingFactor * currentRank) / outDegree;
          for (const v of targets!) {
            if (newRank.has(v)) {
              newRank.set(v, newRank.get(v)! + share);
            }
          }
        } else {
          // Dangling node handling: distribute rank evenly to all nodes
          const share = (dampingFactor * currentRank) / N;
          for (const v of nodes) {
            newRank.set(v, newRank.get(v)! + share);
          }
        }
      }

      rank = newRank;
    }

    // Find max score for normalization
    let maxScore = 0;
    for (const [, s] of rank.entries()) {
      if (s > maxScore) maxScore = s;
    }
    if (maxScore === 0) maxScore = 1;

    for (const node of nodes) {
      const normalized = (rank.get(node) || 0) / maxScore;
      let recommendedTier: 'normal' | 'medium' | 'aggressive' = 'aggressive';

      if (normalized > 0.15) {
        recommendedTier = 'normal';
      } else if (normalized > 0.05) {
        recommendedTier = 'medium';
      }

      scoresMap.set(path.resolve(node), {
        filePath: path.resolve(node),
        score: Math.round(normalized * 1000) / 1000,
        recommendedTier
      });
    }

    return scoresMap;
  }
}

import * as path from 'path';
import { promises as fs } from 'fs';
