export interface BlastRadiusReport {
  targetFile: string;
  forwardDeps: Map<number, string[]>;
  reverseDeps: Map<number, string[]>;
  totalAffectedFiles: number;
  riskLevel: 'low' | 'medium' | 'high' | 'critical';
}

export class ImportGraph {
  // Map of absolute filePath -> Set of absolute imported filePaths
  private graph = new Map<string, Set<string>>();
  private parser: Parser;

  constructor(parser: Parser) {
    this.parser = parser;
  }

  /**
   * Clears the dependency graph.
   */
  clear() {
    this.graph.clear();
  }

  /**
   * Parses a file, extracts its imports/require statements, and updates the dependency graph.
   */
  async parseFileImports(filePath: string, code: string, loadedLanguages: Map<string, Parser.Language>): Promise<void> {
    const absPath = path.resolve(filePath);
    const langInfo = getLanguageInfoForFile(filePath);
    if (!langInfo) return;

    const language = loadedLanguages.get(langInfo.grammarName);
    if (!language) return;

    this.parser.setLanguage(language);
    const tree = this.parser.parse(code);
    if (!tree) return;

    const imports = new Set<string>();
    const fileDir = path.dirname(absPath);

    const traverse = (node: Parser.SyntaxNode) => {
      const type = node.type;

      if (type === 'import_statement') {
        for (let i = 0; i < node.childCount; i++) {
          const child = node.child(i)!;
          if (child.type === 'string') {
            const rawPath = child.text.replace(/['"]/g, '');
            imports.add(rawPath);
          }
        }
      } else if (type === 'call_expression') {
        const funcNode = node.child(0);
        const argsNode = node.child(1);
        if (funcNode && funcNode.text === 'require' && argsNode && argsNode.type === 'arguments') {
          for (let i = 0; i < argsNode.childCount; i++) {
            const arg = argsNode.child(i)!;
            if (arg.type === 'string') {
              const rawPath = arg.text.replace(/['"]/g, '');
              imports.add(rawPath);
            }
          }
        }
      }

      for (let i = 0; i < node.childCount; i++) {
        traverse(node.child(i)!);
      }
    };

    traverse(tree.rootNode);

    const resolvedImports = new Set<string>();

    for (const rawPath of imports) {
      if (rawPath.startsWith('.')) {
        const resolvedBase = path.resolve(fileDir, rawPath);
        const possibleExtensions = ['.ts', '.tsx', '.js', '.jsx', '.py', '.go', '.rs'];
        const currentExt = path.extname(rawPath).toLowerCase();

        if (possibleExtensions.includes(currentExt)) {
          resolvedImports.add(resolvedBase);
        } else {
          for (const ext of possibleExtensions) {
            resolvedImports.add(resolvedBase + ext);
          }
        }
      }
    }

    if (resolvedImports.size > 0) {
      this.graph.set(absPath, resolvedImports);
    }
  }

  /**
   * Retrieves the 1-hop dependencies of a file that exist in the workspace.
   */
  async getDirectDependencies(filePath: string): Promise<string[]> {
    const absPath = path.resolve(filePath);
    const deps = this.graph.get(absPath);
    if (!deps) return [];

    const activeDeps: string[] = [];
    for (const dep of deps) {
      try {
        const stat = await fs.stat(dep);
        if (stat.isFile()) {
          activeDeps.push(dep);
        }
      } catch {}
    }
    return activeDeps;
  }

  /**
   * Builds reverse dependency map: targetFilePath -> Set of source filePaths that import target.
   */
  buildReverseGraph(): Map<string, Set<string>> {
    const reverseGraph = new Map<string, Set<string>>();

    for (const [source, targets] of this.graph.entries()) {
      for (const target of targets) {
        let sources = reverseGraph.get(target);
        if (!sources) {
          sources = new Set<string>();
          reverseGraph.set(target, sources);
        }
        sources.add(source);
      }
    }

    return reverseGraph;
  }

  /**
   * Returns all files within N hops of forward dependencies (what this file imports).
   */
  getNHopDependencies(filePath: string, maxHops = 3): Map<number, string[]> {
    const absPath = path.resolve(filePath);
    const result = new Map<number, string[]>();
    const visited = new Set<string>([absPath]);

    let currentLevel = [absPath];

    for (let hop = 1; hop <= maxHops; hop++) {
      const nextLevel: string[] = [];
      for (const node of currentLevel) {
        const targets = this.graph.get(node);
        if (targets) {
          for (const target of targets) {
            if (!visited.has(target)) {
              visited.add(target);
              nextLevel.push(target);
            }
          }
        }
      }

      if (nextLevel.length === 0) break;
      result.set(hop, nextLevel);
      currentLevel = nextLevel;
    }

    return result;
  }

  /**
   * Returns all files within N hops of reverse dependencies (what files import this file).
   */
  getReverseDependencies(filePath: string, maxHops = 3): Map<number, string[]> {
    const absPath = path.resolve(filePath);
    const reverseGraph = this.buildReverseGraph();
    const result = new Map<number, string[]>();
    const visited = new Set<string>([absPath]);

    let currentLevel = [absPath];

    for (let hop = 1; hop <= maxHops; hop++) {
      const nextLevel: string[] = [];
      for (const node of currentLevel) {
        const sources = reverseGraph.get(node);
        if (sources) {
          for (const source of sources) {
            if (!visited.has(source)) {
              visited.add(source);
              nextLevel.push(source);
            }
          }
        }
      }

      if (nextLevel.length === 0) break;
      result.set(hop, nextLevel);
      currentLevel = nextLevel;
    }

    return result;
  }

  /**
   * Computes the full Blast Radius for a file modification.
   */
  getBlastRadius(filePath: string, maxHops = 3): BlastRadiusReport {
    const absPath = path.resolve(filePath);
    const forwardDeps = this.getNHopDependencies(absPath, maxHops);
    const reverseDeps = this.getReverseDependencies(absPath, maxHops);

    const affectedSet = new Set<string>();

    for (const files of forwardDeps.values()) {
      for (const f of files) affectedSet.add(f);
    }
    for (const files of reverseDeps.values()) {
      for (const f of files) affectedSet.add(f);
    }

    const totalAffectedFiles = affectedSet.size;
    let riskLevel: 'low' | 'medium' | 'high' | 'critical' = 'low';

    if (totalAffectedFiles > 15) riskLevel = 'critical';
    else if (totalAffectedFiles > 7) riskLevel = 'high';
    else if (totalAffectedFiles > 2) riskLevel = 'medium';

    return {
      targetFile: absPath,
      forwardDeps,
      reverseDeps,
      totalAffectedFiles,
      riskLevel,
    };
  }

  /**
   * Returns all known file node paths in the dependency graph.
   */
  getAllNodes(): Set<string> {
    const nodes = new Set<string>();
    for (const [source, targets] of this.graph.entries()) {
      nodes.add(source);
      for (const target of targets) {
        nodes.add(target);
      }
    }
    return nodes;
  }

  /**
   * Computes the in-degree count (how many files import each file).
   */
  getInDegreeMap(): Map<string, number> {
    const inDegrees = new Map<string, number>();
    for (const node of this.getAllNodes()) {
      inDegrees.set(node, 0);
    }
    for (const [, targets] of this.graph.entries()) {
      for (const target of targets) {
        inDegrees.set(target, (inDegrees.get(target) || 0) + 1);
      }
    }
    return inDegrees;
  }

  /**
   * Returns a map of source file -> Set of imported target files (out-edges).
   */
  getOutEdgesMap(): Map<string, Set<string>> {
    return this.graph;
  }
}

import * as path from 'path';

export interface LanguageInfo {
  grammarName: string; // e.g. 'typescript', 'python'
  wasmFile: string;    // e.g. 'tree-sitter-typescript.wasm'
}

export const LANGUAGE_REGISTRY: Record<string, LanguageInfo> = {
  '.ts': { grammarName: 'typescript', wasmFile: 'tree-sitter-typescript.wasm' },
  '.tsx': { grammarName: 'tsx', wasmFile: 'tree-sitter-tsx.wasm' },
  '.js': { grammarName: 'javascript', wasmFile: 'tree-sitter-javascript.wasm' },
  '.jsx': { grammarName: 'javascript', wasmFile: 'tree-sitter-javascript.wasm' },
  '.py': { grammarName: 'python', wasmFile: 'tree-sitter-python.wasm' },
  '.go': { grammarName: 'go', wasmFile: 'tree-sitter-go.wasm' },
  '.rs': { grammarName: 'rust', wasmFile: 'tree-sitter-rust.wasm' },
  '.java': { grammarName: 'java', wasmFile: 'tree-sitter-java.wasm' },
  '.cs': { grammarName: 'c_sharp', wasmFile: 'tree-sitter-c_sharp.wasm' }
};

/**
 * Returns the language registry info based on file path extension.
 */
export function getLanguageInfoForFile(filePath: string): LanguageInfo | null {
  const ext = path.extname(filePath).toLowerCase();
  return LANGUAGE_REGISTRY[ext] || null;
}

import * as path from 'path';
import * as fs from 'fs';
import Parser from 'web-tree-sitter';
import { getLanguageInfoForFile, LANGUAGE_REGISTRY } from './languageRegistry';
import { getConfig } from './configLoader';

export class CodeCompressionEngine {
  private parser: Parser | null = null;
  private loadedLanguages = new Map<string, Parser.Language>();
  private isInitialized = false;
  private wasmFallbackMode = false;

  public getParser(): Parser | null {
    return this.parser;
  }

  public getLoadedLanguages(): Map<string, Parser.Language> {
    return this.loadedLanguages;
  }

  async init(): Promise<void> {
    if (this.isInitialized) return;

    try {
      // Multi-tier path resolution for web-tree-sitter.wasm
      const candidateWasmDirs = [
        path.resolve(__dirname, '../../node_modules/web-tree-sitter'),
        path.resolve(__dirname, '../node_modules/web-tree-sitter'),
        path.resolve(__dirname, './wasm'),
        process.cwd()
      ];

      let resolvedWasmDir = candidateWasmDirs[0];
      for (const dir of candidateWasmDirs) {
        if (fs.existsSync(path.join(dir, 'tree-sitter.wasm'))) {
          resolvedWasmDir = dir;
          break;
        }
      }

      await Parser.init({
        locateFile(scriptName: string) {
          return path.join(resolvedWasmDir, scriptName);
        }
      });

      this.parser = new Parser();

      // Multi-tier resolution for tree-sitter-wasms
      const candidateWasmsDirs = [
        path.resolve(__dirname, '../../node_modules/tree-sitter-wasms/out'),
        path.resolve(__dirname, '../node_modules/tree-sitter-wasms/out'),
        path.resolve(__dirname, './wasm')
      ];

      let resolvedWasmsDir = candidateWasmsDirs[0];
      for (const dir of candidateWasmsDirs) {
        if (fs.existsSync(dir)) {
          resolvedWasmsDir = dir;
          break;
        }
      }

      for (const key of Object.keys(LANGUAGE_REGISTRY)) {
        const info = LANGUAGE_REGISTRY[key];
        if (!this.loadedLanguages.has(info.grammarName)) {
          const langPath = path.join(resolvedWasmsDir, info.wasmFile);
          if (fs.existsSync(langPath)) {
            try {
              const lang = await Parser.Language.load(langPath);
              this.loadedLanguages.set(info.grammarName, lang);
            } catch {
              // Ignore single language load failures
            }
          }
        }
      }
    } catch {
      // WASM load failure fallback mode: switch gracefully to regex fallback
      this.wasmFallbackMode = true;
    } finally {
      this.isInitialized = true;
    }
  }

  async compress(code: string, filePath: string, tier: 'normal' | 'medium' | 'aggressive'): Promise<string> {
    if (!this.isInitialized) {
      await this.init();
    }

    if (this.wasmFallbackMode || !this.parser) {
      return this.fallbackCompress(code, tier);
    }

    // Resolve grammar using languageRegistry
    const langInfo = getLanguageInfoForFile(filePath);
    let language: Parser.Language | undefined;
    if (langInfo) {
      language = this.loadedLanguages.get(langInfo.grammarName);
    }

    if (!language) {
      return this.fallbackCompress(code, tier);
    }

    this.parser.setLanguage(language);

    try {
      const tree = this.parser.parse(code);
      if (!tree) {
        return this.fallbackCompress(code, tier);
      }
      const root = tree.rootNode;

      if (tier === 'normal') {
        // Strip license headers even in normal tier, but keep all code lines
        const replacements: { start: number; end: number; text: string }[] = [];
        const cleanComments = (node: Parser.SyntaxNode) => {
          if (node.type.includes('comment') && this.isLicenseHeader(node)) {
            replacements.push({ start: node.startIndex, end: node.endIndex, text: '' });
          }
          for (let i = 0; i < node.childCount; i++) {
            cleanComments(node.child(i)!);
          }
        };
        cleanComments(root);

        replacements.sort((a, b) => b.start - a.start);
        let cleanedCode = code;
        for (const r of replacements) {
          cleanedCode = cleanedCode.slice(0, r.start) + r.text + cleanedCode.slice(r.end);
        }
        return this.fallbackCompress(cleanedCode, 'normal');
      }

      const replacements: { start: number; end: number; text: string }[] = [];

      // Helper to check if a node is a license header
      const isLicense = (node: Parser.SyntaxNode) => this.isLicenseHeader(node);

      // Helper to collect replacements
      const traverse = (node: Parser.SyntaxNode, isTopLevel = false) => {
        const type = node.type;

        // Smart Comment Handling
        if (type.includes('comment')) {
          if (isLicense(node)) {
            replacements.push({
              start: node.startIndex,
              end: node.endIndex,
              text: ''
            });
            return;
          }

          if (tier === 'medium' || tier === 'aggressive') {
            // Keep JSDoc (/** ... */) or Rust/C# triple-slash (/// ...)
            const isDocComment = node.text.startsWith('/**') || node.text.startsWith('///');
            if (!isDocComment) {
              const config = getConfig();
              const preservePatterns = config.preserveCommentPatterns || [];
              const isPreserved = preservePatterns.some((pattern) => node.text.includes(pattern));
              if (!isPreserved) {
                replacements.push({
                  start: node.startIndex,
                  end: node.endIndex,
                  text: ''
                });
              }
            }
          }
          return;
        }

        if (tier === 'aggressive') {
          // Collapse function/method bodies
          const isFunctionBlock =
            (type === 'statement_block' &&
              (node.parent?.type === 'function_declaration' ||
                node.parent?.type === 'method_definition' ||
                node.parent?.type === 'function_expression' ||
                node.parent?.type === 'arrow_function')) ||
            (type === 'block' &&
              (node.parent?.type === 'function_definition' ||
                node.parent?.type === 'function_declaration' ||
                node.parent?.type === 'method_declaration' ||
                node.parent?.type === 'function_item' ||
                node.parent?.type === 'method_declaration' ||
                node.parent?.type === 'constructor_declaration')) ||
            (type === 'constructor_body');

          if (isFunctionBlock) {
            let docstringNode: Parser.SyntaxNode | null = null;
            if (node.type === 'block' && node.childCount > 0) {
              const firstChild = node.child(0)!;
              if (firstChild.type === 'expression_statement' && firstChild.childCount > 0 && firstChild.child(0)!.type === 'string') {
                docstringNode = firstChild;
              }
            }

            if (node.childCount >= 2 && node.child(0)!.text === '{' && node.child(node.childCount - 1)!.text === '}') {
              const firstChild = node.child(0)!;
              const lastChild = node.child(node.childCount - 1)!;
              replacements.push({
                start: firstChild.endIndex,
                end: lastChild.startIndex,
                text: ' ... '
              });
            } else if (docstringNode) {
              replacements.push({
                start: docstringNode.endIndex,
                end: node.endIndex,
                text: '\n    ...'
              });
            } else {
              replacements.push({
                start: node.startIndex,
                end: node.endIndex,
                text: ' ...'
              });
            }
            return;
          }

          if (type === 'arrow_function' && node.lastChild && node.lastChild.type !== 'statement_block') {
            const bodyNode = node.lastChild;
            replacements.push({
              start: bodyNode.startIndex,
              end: bodyNode.endIndex,
              text: '...'
            });
            return;
          }

          if (isTopLevel && type === 'lexical_declaration') {
            let collapsedAny = false;
            for (let i = 0; i < node.childCount; i++) {
              const child = node.child(i)!;
              if (child.type === 'variable_declarator') {
                const valueNode = child.child(child.childCount - 1);
                if (valueNode && (valueNode.type === 'object' || valueNode.type === 'array' || valueNode.type.startsWith('jsx_'))) {
                  replacements.push({
                    start: valueNode.startIndex,
                    end: valueNode.endIndex,
                    text: valueNode.type === 'array' ? '[...]' : '{...}'
                  });
                  collapsedAny = true;
                }
              }
            }
            if (collapsedAny) {
              return;
            }
          }

          if (type === 'jsx_element') {
            const openTag = node.child(0);
            const closeTag = node.child(node.childCount - 1);
            if (openTag && closeTag && openTag !== closeTag) {
              replacements.push({
                start: openTag.endIndex,
                end: closeTag.startIndex,
                text: '...'
              });
            }
            return;
          }
          if (type === 'jsx_self_closing_element') {
            return;
          }
        }

        if (tier === 'medium') {
          const isControlStatement =
            [
              'if_statement', 'for_statement', 'for_in_statement', 'for_of_statement',
              'while_statement', 'do_statement', 'switch_statement', 'try_statement',
              'if_expression', 'for_expression', 'while_expression', 'loop_expression',
              'match_expression', 'expression_switch_statement', 'type_switch_statement',
              'select_statement'
            ].includes(type);

          if (isControlStatement) {
            for (let i = 0; i < node.childCount; i++) {
              const child = node.child(i)!;
              if (child.type === 'statement_block' || child.type === 'block' || child.type === 'switch_body' || child.type === 'switch_block') {
                if (child.childCount >= 2 && child.child(0)!.text === '{' && child.child(child.childCount - 1)!.text === '}') {
                  const first = child.child(0)!;
                  const last = child.child(child.childCount - 1)!;
                  replacements.push({
                    start: first.endIndex,
                    end: last.startIndex,
                    text: ' ... '
                  });
                } else {
                  replacements.push({
                    start: child.startIndex,
                    end: child.endIndex,
                    text: ' ...'
                  });
                }
              } else if (child.type === 'catch_clause') {
                const catchBlock = child.child(child.childCount - 1);
                if (catchBlock && (catchBlock.type === 'statement_block' || catchBlock.type === 'block')) {
                  if (catchBlock.childCount >= 2 && catchBlock.child(0)!.text === '{' && catchBlock.child(catchBlock.childCount - 1)!.text === '}') {
                    const first = catchBlock.child(0)!;
                    const last = catchBlock.child(catchBlock.childCount - 1)!;
                    replacements.push({
                      start: first.endIndex,
                      end: last.startIndex,
                      text: ' ... '
                    });
                  } else {
                    replacements.push({
                      start: catchBlock.startIndex,
                      end: catchBlock.endIndex,
                      text: ' ...'
                    });
                  }
                }
              }
            }
          }
        }

        const count = node.childCount;
        const isChildTopLevel = type === 'program' || type === 'export_statement';
        for (let i = 0; i < count; i++) {
          traverse(node.child(i)!, isChildTopLevel);
        }
      };

      traverse(root, true);

      replacements.sort((a, b) => b.start - a.start);
      let compressedCode = code;
      for (const r of replacements) {
        if (r.start >= 0 && r.end <= compressedCode.length && r.start <= r.end) {
          compressedCode =
            compressedCode.slice(0, r.start) + r.text + compressedCode.slice(r.end);
        }
      }

      return this.fallbackCompress(compressedCode, 'normal');
    } catch {
      return this.fallbackCompress(code, tier);
    }
  }

  private isLicenseHeader(node: Parser.SyntaxNode): boolean {
    if (!node.type.includes('comment')) return false;
    if (node.startIndex > 1500) return false;
    const text = node.text.toLowerCase();
    return (
      text.includes('copyright') ||
      text.includes('license') ||
      text.includes('all rights reserved') ||
      text.includes('authored by')
    );
  }

  private fallbackCompress(code: string, tier: 'normal' | 'medium' | 'aggressive'): string {
    const lines = code.split(/\r?\n/);
    const cleanedLines = lines
      .map((line) => line.trimEnd())
      .filter((line) => line.length > 0);

    if (tier === 'normal') {
      return cleanedLines.join('\n');
    }

    const config = getConfig();
    const preservePatterns = config.preserveCommentPatterns || [];

    const isPreservedComment = (lineText: string): boolean => {
      const trimmed = lineText.trim();
      if (trimmed.startsWith('///') || trimmed.startsWith('/**')) return true;
      return preservePatterns.some((pattern) => trimmed.includes(pattern));
    };

    if (tier === 'medium') {
      const filtered = cleanedLines.filter((line) => {
        const trimmed = line.trim();
        if (trimmed.startsWith('//') || trimmed.startsWith('#')) {
          return isPreservedComment(trimmed);
        }
        return true;
      });
      return filtered.join('\n');
    }

    // Aggressive tier: filter comments + strip debug logging statements
    const debugRegex = /^\s*(console\.(log|debug|trace)|print\(|fmt\.Print)/;
    const filtered = cleanedLines.filter((line) => {
      const trimmed = line.trim();
      if (trimmed.startsWith('//') || trimmed.startsWith('#')) {
        return isPreservedComment(trimmed);
      }
      if (debugRegex.test(trimmed)) {
        return false;
      }
      return true;
    });

    return filtered.join('\n');
  }
}

import * as path from 'path';
import { promises as fs } from 'fs';

export interface ProjectInfo {
  projectType: string;
  excludePatterns: string[];
  alwaysInclude: string[];
}

/**
 * Automatically detects the workspace project type (NodeJS, Go, Rust, Python, Generic)
 * and returns recommended exclude and alwaysInclude paths.
 */
export async function detectProject(workspaceRoot: string): Promise<ProjectInfo> {
  const info: ProjectInfo = {
    projectType: 'generic',
    excludePatterns: ['**/node_modules/**', '**/.git/**'],
    alwaysInclude: []
  };

  const hasFile = async (fileName: string) => {
    return fs.stat(path.join(workspaceRoot, fileName)).then(s => s.isFile()).catch(() => false);
  };

  if (await hasFile('package.json')) {
    info.projectType = 'nodejs';
    info.excludePatterns = [
      '**/node_modules/**',
      '**/dist/**',
      '**/build/**',
      '**/.next/**',
      '**/.nuxt/**',
      '**/*.test.ts',
      '**/*.spec.ts',
      '**/*.stories.tsx'
    ];
  } else if (await hasFile('go.mod')) {
    info.projectType = 'go';
    info.excludePatterns = [
      '**/vendor/**',
      '**/*_test.go'
    ];
  } else if (await hasFile('Cargo.toml')) {
    info.projectType = 'rust';
    info.excludePatterns = [
      '**/target/**',
      '**/*.rs.bk'
    ];
  } else if (
    await hasFile('pyproject.toml') ||
    await hasFile('requirements.txt') ||
    await hasFile('setup.py')
  ) {
    info.projectType = 'python';
    info.excludePatterns = [
      '**/__pycache__/**',
      '**/.venv/**',
      '**/venv/**',
      '**/*.pyc',
      '**/.ipynb_checkpoints/**'
    ];
  }

  return info;
}

import * as path from 'path';

export interface QueryAdaptiveResult {
  extractedSymbols: string[];
  pinnedFiles: string[];
}

/**
 * Extracts key symbols and file paths mentioned in an active user prompt query
 * and resolves corresponding workspace files to temporarily pin at full fidelity ('normal' tier).
 */
export class QueryAdapter {
  /**
   * Tokenizes user prompt, identifies symbols/filenames, and resolves matching workspace files.
   */
  public resolveQueryAdaptivePins(
    activePrompt: string,
    workspaceFiles: string[]
  ): QueryAdaptiveResult {
    if (!activePrompt || !activePrompt.trim()) {
      return { extractedSymbols: [], pinnedFiles: [] };
    }

    // 1. Extract potential code symbols (words, camelCase, snake_case, identifiers, file basenames)
    const rawTokens = activePrompt.match(/[a-zA-Z_0-9./\\]+/g) || [];
    const extractedSymbols = new Set<string>();

    for (const token of rawTokens) {
      if (token.length >= 3) {
        extractedSymbols.add(token.toLowerCase());
        // Handle camelCase splitting (e.g. authService -> auth, service)
        const camelParts = token.replace(/([a-z])([A-Z])/g, '$1 $2').split(' ');
        if (camelParts.length > 1) {
          camelParts.forEach(p => p.length >= 3 && extractedSymbols.add(p.toLowerCase()));
        }
      }
    }

    // 2. Match symbols against workspace files
    const pinnedFilesSet = new Set<string>();

    for (const file of workspaceFiles) {
      const absPath = path.resolve(file);
      const baseName = path.basename(absPath).toLowerCase();
      const baseNameNoExt = path.basename(absPath, path.extname(absPath)).toLowerCase();
      const relPath = file.toLowerCase().replace(/\\/g, '/');

      // Check if any extracted symbol matches file basename or path segment
      for (const symbol of extractedSymbols) {
        if (
          baseName === symbol ||
          baseNameNoExt === symbol ||
          relPath.includes(symbol)
        ) {
          pinnedFilesSet.add(absPath);
          break;
        }
      }
    }

    return {
      extractedSymbols: Array.from(extractedSymbols),
      pinnedFiles: Array.from(pinnedFilesSet)
    };
  }
}

import * as crypto from 'crypto';
import { promises as fs } from 'fs';
import * as path from 'path';

export interface RetrieveCacheEntry {
  original: string;
  filePath: string;
  tier: string;
  createdAt: number;
}

/**
 * Compress-Cache-Retrieve (CCR) Storage Layer.
 * Stores original uncompressed file content indexed by a short SHA-256 hash.
 * Supports disk persistence (.shanaxon/retrieve_cache.json) for cross-session recovery.
 */
export class RetrieveCache {
  private storeMap = new Map<string, RetrieveCacheEntry>();
  private readonly ttlMs: number;
  private readonly maxEntries: number;
  private readonly diskPath: string;
  private flushTimeout: NodeJS.Timeout | null = null;

  constructor(
    ttlMs = 30 * 60 * 1000,
    maxEntries = 500,
    diskPath = '.shanaxon/retrieve_cache.json'
  ) {
    this.ttlMs = ttlMs;
    this.maxEntries = maxEntries;
    this.diskPath = path.resolve(diskPath);
    this.loadFromDisk();
  }

  /**
   * Loads cached entries from disk.
   */
  async loadFromDisk(): Promise<void> {
    try {
      const data = await fs.readFile(this.diskPath, 'utf-8');
      const parsed: Record<string, RetrieveCacheEntry> = JSON.parse(data);
      const now = Date.now();

      this.storeMap.clear();
      for (const [hash, entry] of Object.entries(parsed)) {
        if (now - entry.createdAt <= this.ttlMs) {
          this.storeMap.set(hash, entry);
        }
      }
    } catch {
      // Ignore missing disk cache
    }
  }

  /**
   * Serializes and writes cache to disk atomically using temporary file rename.
   */
  async flushToDisk(): Promise<void> {
    try {
      const dir = path.dirname(this.diskPath);
      await fs.mkdir(dir, { recursive: true });

      const obj: Record<string, RetrieveCacheEntry> = {};
      for (const [hash, entry] of this.storeMap.entries()) {
        obj[hash] = entry;
      }

      const tempPath = `${this.diskPath}.${Date.now()}.${Math.random().toString(36).substring(2, 7)}.tmp`;
      await fs.writeFile(tempPath, JSON.stringify(obj, null, 2), 'utf-8');
      await fs.rename(tempPath, this.diskPath);
    } catch {
      // Fail silently
    }
  }

  private scheduleFlush(): void {
    if (this.flushTimeout) return;
    this.flushTimeout = setTimeout(async () => {
      this.flushTimeout = null;
      await this.flushToDisk();
    }, 2000);
  }

  /**
   * Stores original content and returns an 8-character hash key.
   */
  store(original: string, filePath: string, tier: string): string {
    this.evictExpired();

    const hash = crypto
      .createHash('sha256')
      .update(`${filePath}:${original}`, 'utf-8')
      .digest('hex')
      .substring(0, 8);

    if (this.storeMap.size >= this.maxEntries) {
      const oldestKey = this.storeMap.keys().next().value;
      if (oldestKey) {
        this.storeMap.delete(oldestKey);
      }
    }

    this.storeMap.set(hash, {
      original,
      filePath,
      tier,
      createdAt: Date.now(),
    });

    this.scheduleFlush();
    return hash;
  }

  /**
   * Retrieves original content by hash key.
   * Returns null if expired or not found.
   */
  retrieve(hash: string): RetrieveCacheEntry | null {
    this.evictExpired();
    const entry = this.storeMap.get(hash);
    if (!entry) return null;
    return entry;
  }

  /**
   * Injects retrieve markers into compressed output.
   * Appends `[shanaxon:retrieve hash=<hash>]` footer after compressed content.
   * Only injects for 'medium', 'aggressive', or custom compressed tiers.
   */
  injectMarker(compressed: string, original: string, filePath: string, tier: string): string {
    if (tier === 'normal') {
      return compressed;
    }

    const hash = this.store(original, filePath, tier);
    const marker = `\n\n/* [shanaxon:retrieve hash=${hash}] — Use retrieve_original tool with this hash if full uncompressed source is required */`;
    return `${compressed}${marker}`;
  }

  /**
   * Evicts expired entries based on TTL.
   */
  private evictExpired(): void {
    const now = Date.now();
    for (const [hash, entry] of this.storeMap.entries()) {
      if (now - entry.createdAt > this.ttlMs) {
        this.storeMap.delete(hash);
      }
    }
  }

  /**
   * Returns current cache statistics.
   */
  getStats(): { entries: number; totalOriginalBytes: number } {
    let totalOriginalBytes = 0;
    for (const entry of this.storeMap.values()) {
      totalOriginalBytes += entry.original.length;
    }
    return {
      entries: this.storeMap.size,
      totalOriginalBytes,
    };
  }
}

import { Tokenizer } from './tokenizer';

export interface SchemaCompressionResult {
  compressed: string;
  originalTokens: number;
  compressedTokens: number;
  savingsPct: number;
  toolCount: number;
}

/**
 * MCP Tool Schema Compressor.
 * Solves the #1 MCP complaint in 2026: "schema bloat" where connecting multiple MCP servers
 * consumes 10k–30k tokens in tool definitions alone.
 *
 * Shortens descriptions, removes redundant JSON schema metadata, and flattens nested objects.
 */
export class SchemaCompressor {
  /**
   * Main entry point: compresses an array of tool schema objects.
   */
  compress(schemas: any[]): SchemaCompressionResult {
    if (!Array.isArray(schemas)) {
      schemas = [schemas];
    }

    const toolCount = schemas.length;
    const rawJson = JSON.stringify(schemas, null, 2);
    const originalTokens = Tokenizer.countTokens(rawJson);

    const compressedSchemas = schemas.map((schema) => this.compressSingleSchema(schema));
    const compressedJson = JSON.stringify(compressedSchemas);
    const compressedTokens = Tokenizer.countTokens(compressedJson);

    const savingsPct =
      originalTokens > 0
        ? parseFloat((((originalTokens - compressedTokens) / originalTokens) * 100).toFixed(2))
        : 0;

    return {
      compressed: compressedJson,
      originalTokens,
      compressedTokens,
      savingsPct,
      toolCount,
    };
  }

  /**
   * Compresses a single tool schema definition object.
   */
  private compressSingleSchema(schema: any): any {
    if (!schema || typeof schema !== 'object') return schema;

    const copy: Record<string, any> = {};

    // Copy name
    if (schema.name) copy.name = schema.name;

    // Shorten tool description
    if (schema.description) {
      copy.description = this.shortenDescription(schema.description);
    }

    // Compress input schema
    if (schema.inputSchema) {
      copy.inputSchema = this.simplifySchemaObject(schema.inputSchema, 0);
    }

    return copy;
  }

  /**
   * Shortens a description string to first sentence, max 80 chars.
   */
  private shortenDescription(desc: string): string {
    if (!desc) return '';

    // Take first sentence
    const firstSentence = desc.split(/(?<=[.!?])\s+/)[0];
    if (firstSentence.length <= 80) {
      return firstSentence;
    }
    return `${firstSentence.substring(0, 77)}...`;
  }

  /**
   * Recursively simplifies JSON Schema properties.
   */
  private simplifySchemaObject(schemaObj: any, depth = 0): any {
    if (!schemaObj || typeof schemaObj !== 'object') return schemaObj;

    const result: Record<string, any> = {};

    if (schemaObj.type) result.type = schemaObj.type;
    if (schemaObj.required && Array.isArray(schemaObj.required) && schemaObj.required.length > 0) {
      result.required = schemaObj.required;
    }

    // Collapse deep nesting (>2 levels)
    if (depth >= 2) {
      return result.type ? { type: result.type } : { type: 'object' };
    }

    if (schemaObj.properties && typeof schemaObj.properties === 'object') {
      const props: Record<string, any> = {};
      for (const [propName, propDef] of Object.entries<any>(schemaObj.properties)) {
        if (typeof propDef === 'object') {
          props[propName] = this.simplifySchemaProperty(propDef, depth + 1);
        } else {
          props[propName] = propDef;
        }
      }
      result.properties = props;
    }

    if (schemaObj.items && typeof schemaObj.items === 'object') {
      result.items = this.simplifySchemaObject(schemaObj.items, depth + 1);
    }

    return result;
  }

  /**
   * Simplifies an individual property definition (removes descriptions, examples, defaults).
   */
  private simplifySchemaProperty(propDef: any, depth: number): any {
    const res: Record<string, any> = {};

    if (propDef.type) res.type = propDef.type;
    if (propDef.enum) res.enum = propDef.enum;

    if (propDef.type === 'object' && propDef.properties) {
      res.properties = this.simplifySchemaObject(propDef, depth).properties;
    }

    if (propDef.type === 'array' && propDef.items) {
      res.items = this.simplifySchemaObject(propDef.items, depth);
    }

    return Object.keys(res).length > 0 ? res : { type: propDef.type || 'string' };
  }
}

import { Tokenizer } from './tokenizer';

export type ContentType = 'json' | 'log' | 'terminal' | 'stacktrace' | 'unknown';

export interface CrushResult {
  crushed: string;
  contentType: ContentType;
  originalTokens: number;
  crushedTokens: number;
  savingsPct: number;
}

/**
 * Content-Type-Aware Compression Engine.
 * Intelligently compresses non-code context (JSON API responses, terminal logs, stack traces).
 * Reduces non-code token volume by 60–90% while keeping errors and critical schema fields.
 */
export class SmartCrusher {
  /**
   * Main entry point: auto-detects content type and applies the optimal crusher.
   */
  crush(input: string): CrushResult {
    const contentType = this.detectContentType(input);
    let crushed = input;

    switch (contentType) {
      case 'json':
        crushed = this.crushJson(input);
        break;
      case 'stacktrace':
        crushed = this.crushStackTrace(input);
        break;
      case 'terminal':
        crushed = this.crushTerminal(input);
        break;
      case 'log':
        crushed = this.crushLog(input);
        break;
      default:
        crushed = this.crushGeneric(input);
        break;
    }

    const originalTokens = Tokenizer.countTokens(input);
    const crushedTokens = Tokenizer.countTokens(crushed);
    const savingsPct =
      originalTokens > 0
        ? parseFloat((((originalTokens - crushedTokens) / originalTokens) * 100).toFixed(2))
        : 0;

    return {
      crushed,
      contentType,
      originalTokens,
      crushedTokens,
      savingsPct,
    };
  }

  /**
   * Auto-detects whether input is JSON, Stack Trace, Terminal Dump, or Log file.
   */
  private detectContentType(input: string): ContentType {
    const trimmed = input.trim();

    // Check JSON
    if ((trimmed.startsWith('{') && trimmed.endsWith('}')) || (trimmed.startsWith('[') && trimmed.endsWith(']'))) {
      try {
        JSON.parse(trimmed);
        return 'json';
      } catch {}
    }

    // Check Stack Trace
    if (/(?:Error|Exception|Traceback):[^\n]+\n\s+at /i.test(input) || /File "[^"]+", line \d+/i.test(input)) {
      return 'stacktrace';
    }

    // Check Terminal Dump
    if (
      input.includes('npm ERR!') ||
      input.includes('yarn run') ||
      input.includes('webpack') ||
      input.includes('vite v') ||
      /\[\d{1,2}:\d{2}:\d{2}\]/.test(input) ||
      /\x1b\[[0-9;]*m/.test(input)
    ) {
      return 'terminal';
    }

    // Check Log
    if (/(?:INFO|DEBUG|WARN|ERROR|FATAL|TRACE)[\s:]/i.test(input)) {
      return 'log';
    }

    return 'unknown';
  }

  /**
   * JSON Crusher:
   * - Truncates strings >150 chars
   * - Collapses arrays >3 items to first 2 items + count summary
   * - Prunes null / empty object properties
   * - Preserves critical keys: 'id', 'error', 'status', 'code', 'type', 'message', 'key', 'name'
   */
  private crushJson(input: string): string {
    try {
      const parsed = JSON.parse(input);
      const pruned = this.pruneJsonObject(parsed);
      return JSON.stringify(pruned, null, 2);
    } catch {
      return input;
    }
  }

  private pruneJsonObject(obj: any, depth = 0): any {
    if (obj === null || obj === undefined) return undefined;

    if (typeof obj === 'string') {
      if (obj.length > 150) {
        return `${obj.substring(0, 100)}... [${obj.length - 100} chars truncated]`;
      }
      return obj;
    }

    if (typeof obj !== 'object') return obj;

    if (Array.isArray(obj)) {
      if (obj.length > 3 && depth > 0) {
        const firstTwo = obj.slice(0, 2).map((item) => this.pruneJsonObject(item, depth + 1));
        firstTwo.push(`... [${obj.length - 2} additional items collapsed]` as any);
        return firstTwo;
      }
      return obj.map((item) => this.pruneJsonObject(item, depth + 1));
    }

    const result: Record<string, any> = {};
    const criticalKeys = new Set(['id', '_id', 'error', 'errors', 'status', 'statusCode', 'code', 'type', 'message', 'name', 'key', 'success']);

    for (const [key, val] of Object.entries(obj)) {
      if (val === null || val === undefined || val === '') continue;

      const isCritical = criticalKeys.has(key.toLowerCase());
      if (depth > 2 && !isCritical && typeof val === 'object') {
        result[key] = '[Object]';
        continue;
      }

      const prunedVal = this.pruneJsonObject(val, depth + 1);
      if (prunedVal !== undefined) {
        result[key] = prunedVal;
      }
    }

    return result;
  }

  /**
   * Log Crusher:
   * - Deduplicates consecutive duplicate log lines
   * - Strips ANSI codes
   * - Preserves ERROR / WARN / FATAL lines fully
   * - Summarizes repetitive INFO / DEBUG lines
   */
  private crushLog(input: string): string {
    const cleanInput = this.stripAnsi(input);
    const lines = cleanInput.split('\n');
    const result: string[] = [];

    let prevLine = '';
    let dupCount = 0;

    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed) continue;

      const isImportant = /(?:ERROR|WARN|FATAL|EXCEPTION|CRITICAL)/i.test(trimmed);

      if (trimmed === prevLine && !isImportant) {
        dupCount++;
        continue;
      }

      if (dupCount > 0) {
        result.push(`  └─ [Repeated ${dupCount} times]`);
        dupCount = 0;
      }

      result.push(line);
      prevLine = trimmed;
    }

    if (dupCount > 0) {
      result.push(`  └─ [Repeated ${dupCount} times]`);
    }

    return result.join('\n');
  }

  /**
   * Terminal Crusher:
   * - Strips ANSI color codes and progress spinners
   * - Collapses verbose build tool dumps (npm, webpack, vite)
   */
  private crushTerminal(input: string): string {
    let text = this.stripAnsi(input);
    // Remove spinner lines / carriage return progress overwrites
    text = text.replace(/\r[^\n]*/g, '');

    const lines = text.split('\n').filter((l) => l.trim().length > 0);
    const output: string[] = [];

    let inVerboseDump = false;
    let verboseCount = 0;

    for (const line of lines) {
      const isError = /(?:ERR!|Error:|FAILED|Exception)/i.test(line);
      const isSummary = /(?:built in|timing|completed|success|packages|vulnerability)/i.test(line);

      if (isError || isSummary) {
        if (inVerboseDump && verboseCount > 0) {
          output.push(`[... ${verboseCount} lines of verbose terminal output collapsed ...]`);
          inVerboseDump = false;
          verboseCount = 0;
        }
        output.push(line);
      } else if (line.includes('http://') || line.includes('https://') || line.includes('Local:')) {
        output.push(line);
      } else {
        inVerboseDump = true;
        verboseCount++;
      }
    }

    if (inVerboseDump && verboseCount > 0) {
      output.push(`[... ${verboseCount} lines of verbose terminal output collapsed ...]`);
    }

    return output.join('\n');
  }

  /**
   * Stack Trace Crusher:
   * Keeps error message + first 3 stack frames + last stack frame.
   */
  private crushStackTrace(input: string): string {
    const lines = input.split('\n');
    if (lines.length <= 6) return input;

    const errorLine = lines[0];
    const frameLines = lines.slice(1).filter((l) => l.trim().startsWith('at ') || l.trim().startsWith('File '));

    if (frameLines.length <= 4) return input;

    const firstThree = frameLines.slice(0, 3);
    const lastOne = frameLines[frameLines.length - 1];
    const collapsedCount = frameLines.length - 4;

    return [
      errorLine,
      ...firstThree,
      `    ... [${collapsedCount} internal stack frames collapsed]`,
      lastOne,
    ].join('\n');
  }

  private crushGeneric(input: string): string {
    return this.crushLog(input);
  }

  private stripAnsi(str: string): string {
    return str.replace(/\x1b\[[0-9;]*[a-zA-Z]/g, '');
  }
}

export type VerbosityLevel = 'minimal' | 'compact' | 'standard';

export interface TersePrompt {
  systemInstruction: string;
  level: VerbosityLevel;
  estimatedOutputReduction: string;
}

/**
 * Output Token Optimization Layer (Caveman-Style Compression).
 * Generates system prompt instructions that constrain the LLM to output concise,
 * filler-free technical responses, reducing output tokens by 30–75%.
 */
export function getTersePrompt(level: VerbosityLevel = 'compact'): TersePrompt {
  switch (level) {
    case 'minimal':
      return {
        level: 'minimal',
        estimatedOutputReduction: '60–75% output tokens saved',
        systemInstruction: `[SYSTEM DIRECTIVE: TERSE MODE MINIMAL]
You MUST optimize for extreme output token brevity:
- Zero pleasantries, zero fluff, zero introductory or concluding sentences.
- Use telegraphic/caveman style for explanations (omit articles "a", "an", "the").
- Provide raw code solutions directly. Keep inline comments minimal.
- Format answers with bullet points or raw markdown blocks only.`,
      };

    case 'compact':
      return {
        level: 'compact',
        estimatedOutputReduction: '30–50% output tokens saved',
        systemInstruction: `[SYSTEM DIRECTIVE: TERSE MODE COMPACT]
Respond concisely and direct-to-the-point:
- Avoid repetitive summary paragraphs or conversational filler.
- Focus output on raw code blocks, diffs, and essential technical bullet points.
- State reasons briefly before code snippets; omit step-by-step rewording of obvious logic.`,
      };

    case 'standard':
    default:
      return {
        level: 'standard',
        estimatedOutputReduction: '0% (Standard verbosity)',
        systemInstruction: `[SYSTEM DIRECTIVE: STANDARD MODE]
Respond normally with complete explanations, formatted markdown, and standard conversational tone.`,
      };
  }
}

import React, { useState, useCallback } from 'react';

export interface MoodLog {
  id: string;
  score: number;
  note: string;
  timestamp: number;
}

/**
 * MoodTracker Component - Tracks and analyzes user mood patterns.
 */
export const MoodTracker: React.FC = () => {
  const [logs, setLogs] = useState<MoodLog[]>([]);
  const [currentNote, setCurrentNote] = useState('');

  // Handle adding a new log
  const handleAddLog = useCallback((score: number) => {
    if (score < 1 || score > 5) {
      console.warn("Invalid score range");
      return;
    }

    const newLog: MoodLog = {
      id: Math.random().toString(),
      score,
      note: currentNote,
      timestamp: Date.now(),
    };

    setLogs((prev: MoodLog[]) => {
      const updated = [...prev, newLog];
      for (let i = 0; i < updated.length; i++) {
        if (updated[i].score > 3) {
          console.log("High mood score logged!");
        }
      }
      return updated;
    });

    setCurrentNote('');
  }, [currentNote]);

  // Render method
  return (
    <div className="mood-tracker-container" style={{ padding: 20 }}>
      <h1>Open-Source Mood Tracker</h1>
      <textarea
        value={currentNote}
        onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setCurrentNote(e.target.value)}
        placeholder="How are you feeling?"
      />
      <div className="button-group">
        {[1, 2, 3, 4, 5].map((val) => (
          <button key={val} onClick={() => handleAddLog(val)}>
            Score {val}
          </button>
        ))}
      </div>
      <div className="logs-display">
        {logs.map((log: MoodLog) => {
          if (log.score > 3) {
            return <p key={log.id}>😊 {log.note} ({log.score}/5)</p>;
          } else {
            return <p key={log.id}>😐 {log.note} ({log.score}/5)</p>;
          }
        })}
      </div>
    </div>
  );
};

import { UsageTracker } from './usageTracker';

/**
 * Dynamically resolves file tier based on usage learning parameters:
 * - Frequently accessed files promote to normal.
 * - Stale files (untouched > 14 days) demote to aggressive.
 */
export function getAutoTunedTier(
  filePath: string,
  tracker: UsageTracker,
  defaultTier: 'normal' | 'medium' | 'aggressive'
): 'normal' | 'medium' | 'aggressive' {
  const usage = tracker.getUsage(filePath);
  if (!usage) return defaultTier;

  // Rule 1: Promote frequently accessed files
  if (usage.accessCount >= 5) {
    return 'normal';
  }

  // Rule 2: Demote cold/stale files (> 14 days ago)
  const lastAccess = new Date(usage.lastAccessed).getTime();
  const fourteenDaysAgo = Date.now() - 14 * 24 * 60 * 60 * 1000;
  if (lastAccess < fourteenDaysAgo) {
    return 'aggressive';
  }

  return defaultTier;
}

import * as path from 'path';

/**
 * Language-Aware Code Token Estimator.
 * Computes structure-aware BPE token estimates matching Anthropic / OpenAI BPE tokenizers (cl100k_base / o200k_base).
 */
export class Tokenizer {
  /**
   * Estimates exact BPE tokens for code text taking language extension and AST syntax density into account.
   */
  public static countTokens(text: string, filePath?: string): number {
    if (!text || text.trim().length === 0) {
      return 0;
    }

    const totalChars = text.length;
    const ext = filePath ? path.extname(filePath).toLowerCase() : '';

    // Calculate structural metrics
    const lines = text.split('\n');
    let commentChars = 0;
    let codeChars = 0;
    let whitespaceChars = 0;

    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed) {
        whitespaceChars += line.length;
      } else if (trimmed.startsWith('//') || trimmed.startsWith('#') || trimmed.startsWith('/*') || trimmed.startsWith('*')) {
        commentChars += line.length;
      } else {
        codeChars += line.length;
      }
    }

    // Assign character-per-token ratios based on syntax density
    let codeRatio = 3.0; // Default source code ratio
    if (ext === '.json' || ext === '.yaml' || ext === '.yml') {
      codeRatio = 2.4; // Data formats have higher token density
    } else if (ext === '.ts' || ext === '.tsx' || ext === '.js' || ext === '.jsx') {
      codeRatio = 2.8; // JS/TS contains many punctuation symbols
    } else if (ext === '.py' || ext === '.go' || ext === '.rs' || ext === '.java') {
      codeRatio = 3.1;
    }

    const commentRatio = 4.0; // Natural language comments have lower token density
    const whitespaceRatio = 5.0; // Indentation whitespace collapses in BPE

    const estimatedCodeTokens = codeChars / codeRatio;
    const estimatedCommentTokens = commentChars / commentRatio;
    const estimatedWhitespaceTokens = whitespaceChars / whitespaceRatio;

    const totalEstimated = Math.ceil(estimatedCodeTokens + estimatedCommentTokens + estimatedWhitespaceTokens);
    return Math.max(1, totalEstimated);
  }
}

import { promises as fs, existsSync, readFileSync } from 'fs';
import * as path from 'path';

export interface FileUsage {
  accessCount: number;
  lastAccessed: string;
}

/**
 * Tracks usage frequencies and access timestamps to power auto-tuning strategies.
 * Uses atomic async disk persistence (.tmp -> rename) to prevent file corruption.
 */
export class UsageTracker {
  private usagePath: string;
  private usage: Record<string, FileUsage> = {};
  private saveTimeout: NodeJS.Timeout | null = null;

  constructor(workspaceRoot: string) {
    this.usagePath = path.resolve(workspaceRoot, '.shanaxon/usage.json');
    this.loadUsage();
  }

  private loadUsage() {
    try {
      if (existsSync(this.usagePath)) {
        const data = readFileSync(this.usagePath, 'utf-8');
        this.usage = JSON.parse(data);
      }
    } catch {
      this.usage = {};
    }
  }

  private scheduleSave() {
    if (this.saveTimeout) return;
    this.saveTimeout = setTimeout(async () => {
      this.saveTimeout = null;
      await this.flushToDisk();
    }, 2000);
  }

  /**
   * Serializes and writes usage metrics to disk using atomic temp file renaming.
   */
  async flushToDisk(): Promise<void> {
    try {
      const dir = path.dirname(this.usagePath);
      await fs.mkdir(dir, { recursive: true });
      const tempPath = `${this.usagePath}.${Date.now()}.${Math.random().toString(36).substring(2, 7)}.tmp`;
      await fs.writeFile(tempPath, JSON.stringify(this.usage, null, 2), 'utf-8');
      await fs.rename(tempPath, this.usagePath);
    } catch {
      // Fail silently
    }
  }

  recordAccess(filePath: string) {
    const absPath = path.resolve(filePath);
    const entry = this.usage[absPath] || { accessCount: 0, lastAccessed: '' };
    entry.accessCount++;
    entry.lastAccessed = new Date().toISOString();
    this.usage[absPath] = entry;
    this.scheduleSave();
  }

  getUsage(filePath: string): FileUsage | null {
    const absPath = path.resolve(filePath);
    return this.usage[absPath] || null;
  }

  async clear(): Promise<void> {
    this.usage = {};
    await this.flushToDisk();
  }
}

