import * as path from 'path';
import { promises as fs } from 'fs';
import ignore from 'ignore';
import { isSensitiveFile, validatePath } from './guardrails';
import { getLanguageInfoForFile } from './languageRegistry';

export class WorkspaceIndexer {
  private workspaceRoot: string;
  private maxDepth: number;
  private maxFiles: number;

  constructor(workspaceRoot: string, maxDepth = 8, maxFiles = 5000) {
    this.workspaceRoot = path.resolve(workspaceRoot);
    this.maxDepth = maxDepth;
    this.maxFiles = maxFiles;
  }

  /**
   * Crawls the workspace concurrently, respects gitignore and shanaxonignore patterns,
   * enforces depth and max file caps to prevent heap OOM crashes in giant monorepos.
   */
  async indexWorkspace(targetDir: string): Promise<string[]> {
    const absoluteTarget = path.isAbsolute(targetDir)
      ? path.resolve(targetDir)
      : path.resolve(this.workspaceRoot, targetDir);

    const isValid = await validatePath(absoluteTarget, this.workspaceRoot);
    if (!isValid) {
      throw new Error(`Access Denied: target directory "${targetDir}" is outside the workspace.`);
    }

    const effectiveRoot = absoluteTarget;

    // Initialize gitignore parser
    const ig = ignore();

    ig.add([
      'node_modules',
      '.git',
      'dist',
      'build',
      '.gemini',
      'telemetry_ledger.json',
      '.env',
      '.env.*',
      '*.pem',
      '*.key',
      '*.p12',
      '*.pfx',
      'id_rsa',
      'id_ed25519'
    ]);

    const gitignorePath = path.join(effectiveRoot, '.gitignore');
    try {
      const gitignoreContent = await fs.readFile(gitignorePath, 'utf-8');
      ig.add(gitignoreContent);
    } catch {}

    for (const ignoreFileName of ['.shanaxonignore', '.dharoharignore']) {
      const ignoreFilePath = path.join(effectiveRoot, ignoreFileName);
      try {
        const ignoreContent = await fs.readFile(ignoreFilePath, 'utf-8');
        ig.add(ignoreContent);
      } catch {}
    }

    const matchedFiles: string[] = [];

    const walk = async (currentDir: string, currentDepth: number) => {
      if (currentDepth > this.maxDepth || matchedFiles.length >= this.maxFiles) {
        return;
      }

      let entries;
      try {
        entries = await fs.readdir(currentDir, { withFileTypes: true });
      } catch {
        return;
      }

      const tasks = entries.map(async (entry) => {
        if (matchedFiles.length >= this.maxFiles) return;

        const fullPath = path.join(currentDir, entry.name);
        const relativeToRoot = path.relative(effectiveRoot, fullPath);
        const normalizedRelPath = relativeToRoot.replace(/\\/g, '/');
        const checkPath = entry.isDirectory() ? `${normalizedRelPath}/` : normalizedRelPath;

        if (ig.ignores(checkPath) || isSensitiveFile(fullPath)) {
          return;
        }

        if (entry.isDirectory()) {
          await walk(fullPath, currentDepth + 1);
        } else if (entry.isFile()) {
          const langInfo = getLanguageInfoForFile(fullPath);
          if (langInfo && matchedFiles.length < this.maxFiles) {
            matchedFiles.push(fullPath);
          }
        }
      });

      await Promise.all(tasks);
    };

    await walk(absoluteTarget, 0);

    matchedFiles.sort((a, b) => a.localeCompare(b));
    return matchedFiles;
  }
}

import * as path from 'path';
import { isSensitiveFile, validatePath } from './guardrails';

/**
 * Manages multiple workspace roots in polyrepo or monorepo environments.
 * Validates path traversal guardrails across all registered workspaces.
 */
export class WorkspaceManager {
  private primaryRoot: string;
  private workspaces: string[] = [];

  constructor(primaryRoot: string, configuredWorkspaces: string[] = []) {
    this.primaryRoot = path.resolve(primaryRoot);
    this.workspaces = [
      this.primaryRoot,
      ...configuredWorkspaces.map((w) => path.resolve(this.primaryRoot, w)),
    ];
  }

  /**
   * Finds the matching workspace root directory for a given file path.
   * Falls back to primaryRoot if the path is outside configured workspaces.
   */
  findWorkspaceForFile(filePath: string): string {
    const absPath = path.resolve(this.primaryRoot, filePath);
    for (const root of this.workspaces) {
      const rel = path.relative(root, absPath);
      if (!rel.startsWith('..') && !path.isAbsolute(rel)) {
        return root;
      }
    }
    return this.primaryRoot;
  }

  /**
   * Validates if a file or directory resides strictly within one of the configured workspaces
   * and is not a sensitive/secret file.
   */
  async validateFileAccess(filePath: string): Promise<string | null> {
    const absPath = path.isAbsolute(filePath)
      ? path.resolve(filePath)
      : path.resolve(this.primaryRoot, filePath);

    if (isSensitiveFile(absPath)) {
      return null;
    }

    for (const root of this.workspaces) {
      const isValid = await validatePath(absPath, root);
      if (isValid) {
        return root;
      }
    }
    return null;
  }

  getWorkspaceRoots(): string[] {
    return this.workspaces;
  }
}

import * as http from 'http';
import * as fs from 'fs';
import * as path from 'path';

/**
 * Starts the zero-dependency Shanaxon Analytics web server.
 * Features dynamic port hunting on EADDRINUSE to support multi-window IDE instances.
 */
export function startDashboardServer(workspaceRoot: string, port = 3333): http.Server {
  const ledgerPath = path.resolve(workspaceRoot, 'telemetry_ledger.json');
  const htmlPath = path.resolve(__dirname, 'index.html');

  const server = http.createServer((req, res) => {
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

    if (req.method === 'OPTIONS') {
      res.writeHead(204);
      res.end();
      return;
    }

    if (req.url === '/' || req.url === '/index.html') {
      fs.readFile(htmlPath, 'utf-8', (err, content) => {
        if (err) {
          res.writeHead(500, { 'Content-Type': 'text/plain' });
          res.end(`Dashboard template index.html not found at path: ${htmlPath}`);
        } else {
          res.writeHead(200, { 'Content-Type': 'text/html' });
          res.end(content);
        }
      });
    } else if (req.url === '/api/metrics') {
      fs.readFile(ledgerPath, 'utf-8', (err, data) => {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        if (err) {
          res.end('[]');
        } else {
          res.end(data || '[]');
        }
      });
    } else {
      res.writeHead(404, { 'Content-Type': 'text/plain' });
      res.end('Not Found');
    }
  });

  const tryListen = (currentPort: number, attemptsRemaining: number) => {
    server.listen(currentPort);
    server.on('error', (err: any) => {
      if (err.code === 'EADDRINUSE' && attemptsRemaining > 0) {
        server.close();
        tryListen(currentPort + 1, attemptsRemaining - 1);
      }
    });
  };

  tryListen(port, 10);
  return server;
}

#!/usr/bin/env node
import * as fs from 'fs';
import * as path from 'path';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { McpCompressionServer } from './server';

function readPackageVersion(): string {
  try {
    const pkgPath = path.resolve(__dirname, '../package.json');
    const parsed = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
    return typeof parsed.version === 'string' ? parsed.version : '6.1.0';
  } catch {
    return '6.1.0';
  }
}

function printHelp(version: string): void {
  console.log(`Shanaxon v${version} — Open-Source Local Context Optimization & FinOps MCP Server

Usage:
  shanaxon                         Start the MCP server over stdio (default for IDE/agent clients)
  shanaxon init [--yes | -y]       Generate .shanaxon.json and register workspace MCP configs
  shanaxon benchmark               Run AST compression benchmark against ./src in current workspace
  shanaxon export [options]        Export telemetry_ledger.json (--format json|csv --out <file>)
  shanaxon dashboard [--port N]    Start the local web analytics dashboard (default port: 3333)
  shanaxon --version | -v          Print version and exit
  shanaxon --help | -h             Show this help message and exit
`);
}

function parsePortArg(args: string[], defaultPort = 3333): number {
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--port' && args[i + 1]) {
      const parsed = Number(args[i + 1]);
      if (Number.isInteger(parsed) && parsed > 0 && parsed <= 65535) return parsed;
    } else if (args[i].startsWith('--port=')) {
      const parsed = Number(args[i].split('=')[1]);
      if (Number.isInteger(parsed) && parsed > 0 && parsed <= 65535) return parsed;
    }
  }
  return defaultPort;
}

async function main(): Promise<void> {
  const args = process.argv.slice(2);
  const cmd = args[0];

  if (cmd === '--version' || cmd === '-v') {
    console.log(readPackageVersion());
    process.exit(0);
  }

  if (cmd === '--help' || cmd === '-h' || cmd === 'help') {
    printHelp(readPackageVersion());
    process.exit(0);
  }

  if (cmd === 'init') {
    const { runInit } = await import('./cli/init');
    await runInit(args.slice(1));
    return;
  }

  if (cmd === 'benchmark') {
    const { runBenchmarkCli } = await import('./core/benchmarkReal');
    await runBenchmarkCli(process.cwd());
    return;
  }

  if (cmd === 'export') {
    const { runExport } = await import('./cli/export');
    await runExport(args.slice(1));
    return;
  }

  if (cmd === 'dashboard') {
    const port = parsePortArg(args.slice(1), 3333);
    const { startDashboardServer } = await import('./dashboard/server');
    const server = startDashboardServer(process.cwd(), port);
    server.on('listening', () => {
      const addr = server.address();
      const activePort = typeof addr === 'object' && addr ? addr.port : port;
      console.log(`Shanaxon Analytics Dashboard listening at http://localhost:${activePort}`);
    });
    return;
  }

  if (cmd && cmd.startsWith('-')) {
    console.error(`Unknown option: ${cmd}`);
    console.error('Run "shanaxon --help" for usage.');
    process.exit(1);
  }

  if (cmd) {
    console.error(`Unknown command: ${cmd}`);
    console.error('Run "shanaxon --help" for usage.');
    process.exit(1);
  }

  const mcpServer = new McpCompressionServer();
  const transport = new StdioServerTransport();

  await mcpServer.server.connect(transport);
  console.error('Shanaxon MCP server running on stdio');
}

main().catch((error) => {
  console.error('Server crashed with error:', error);
  process.exit(1);
});

import { ExecutionAttempt } from '../types';

/**
 * Tracks execution attempts and calculates actual retry/failure costs for requests.
 */
export class AttemptTracker {
  private static instance: AttemptTracker;
  private attemptsMap: Map<string, ExecutionAttempt[]> = new Map();

  private constructor() {}

  public static getInstance(): AttemptTracker {
    if (!AttemptTracker.instance) {
      AttemptTracker.instance = new AttemptTracker();
    }
    return AttemptTracker.instance;
  }

  /**
   * Records a new execution attempt for a request ID.
   */
  public recordAttempt(attempt: Omit<ExecutionAttempt, 'timestamp' | 'totalCost'>): ExecutionAttempt {
    const totalCost = parseFloat((attempt.inputCost + attempt.outputCost).toFixed(6));
    const fullAttempt: ExecutionAttempt = {
      ...attempt,
      totalCost,
      timestamp: Date.now(),
    };

    const existing = this.attemptsMap.get(attempt.requestId) || [];
    existing.push(fullAttempt);
    this.attemptsMap.set(attempt.requestId, existing);

    return fullAttempt;
  }

  /**
   * Gets all recorded attempts for a request ID.
   */
  public getAttempts(requestId: string): ExecutionAttempt[] {
    return this.attemptsMap.get(requestId) || [];
  }

  /**
   * Calculates total financial cost of all failed prior attempts (retries) for a request.
   */
  public calculateRetryCost(requestId: string): number {
    const attempts = this.getAttempts(requestId);
    if (attempts.length <= 1) return 0;

    let retryCost = 0;
    // Accumulate cost of all attempts before the final successful attempt or all failed attempts
    for (let i = 0; i < attempts.length - 1; i++) {
      retryCost += attempts[i].totalCost;
    }
    return parseFloat(retryCost.toFixed(6));
  }

  /**
   * Clears attempt records for testing or tenant cleanup.
   */
  public clear(): void {
    this.attemptsMap.clear();
  }
}

import { CostBreakdown } from '../types';
import { calculateModelCost } from './economicsEngine';
import { Tokenizer } from '../core/tokenizer';

export interface BaselineAnalysisOptions {
  model: string;
  provider?: string;
  originalCode?: string;
  filePath?: string;
  explicitInputTokens?: number;
  explicitOutputTokens?: number;
  outputTokenRatio?: number;
  confidence?: 'measured' | 'estimated';
}

export interface BaselineAnalysisResult {
  inputTokens: number;
  outputTokens: number;
  breakdown: CostBreakdown;
  confidence: 'measured' | 'estimated';
}

/**
 * Analyzes or estimates the baseline model token usage and financial cost before optimization.
 */
export function analyzeBaseline(options: BaselineAnalysisOptions): BaselineAnalysisResult {
  let inputTokens = options.explicitInputTokens || 0;

  if (!options.explicitInputTokens && options.originalCode) {
    inputTokens = Tokenizer.countTokens(options.originalCode, options.filePath);
  }

  let outputTokens = options.explicitOutputTokens;
  if (outputTokens === undefined) {
    // Default estimated output tokens is 5% of input tokens or a minimum of 250 tokens
    const ratio = options.outputTokenRatio ?? 0.05;
    outputTokens = Math.max(250, Math.ceil(inputTokens * ratio));
  }

  const confidence = options.confidence || (options.explicitInputTokens !== undefined ? 'measured' : 'estimated');

  const breakdown = calculateModelCost({
    provider: options.provider,
    model: options.model,
    inputTokens,
    outputTokens,
  });

  return {
    inputTokens,
    outputTokens,
    breakdown,
    confidence,
  };
}

import { promises as fs } from 'fs';
import * as path from 'path';
import { MemoryEntry, TaskProfile } from '../types';
import { recallMemory } from './criticalMemory';

export interface EqualizedContextResult {
  originalPrompt: string;
  enrichedPrompt: string;
  injectedMemories: MemoryEntry[];
  suggestedFiles: string[];
  missingContext: string[];
  warnings: string[];
  equalizationApplied: boolean;
  capabilityGapBefore: number; // 0 - 100
  capabilityGapAfter: number;  // 0 - 100
}

/**
 * Automatically bridges capability gaps by augmenting novice prompts with relevant architectural constraints,
 * critical memories, and real workspace file context that an expert engineer would manually supply.
 */
export async function equalizeContext(
  userPrompt: string,
  workspaceRoot: string,
  taskProfile: TaskProfile
): Promise<EqualizedContextResult> {
  const warnings: string[] = [];
  const suggestedFiles: string[] = [];
  const missingContext: string[] = [];
  const contextAdditions: string[] = [];

  // Calculate Initial Capability Gap (0 - 100)
  let capabilityGapBefore = 0;

  // 1. Check prompt completeness / brevity
  if (userPrompt.trim().length < 50) {
    capabilityGapBefore += 35;
    missingContext.push('Prompt is extremely brief (< 50 chars); lacks explicit task constraints and target file pointers.');
  } else if (userPrompt.trim().length < 120) {
    capabilityGapBefore += 20;
    missingContext.push('Prompt is moderately brief; lacks detailed execution context.');
  }

  // 2. Check task-specific missing context
  if (taskProfile.taskType === 'bug_investigation') {
    if (!/stack|trace|error|exception|fail|line/i.test(userPrompt)) {
      capabilityGapBefore += 30;
      missingContext.push('Bug report prompt missing runtime exception or stack trace details.');
    }
  } else if (taskProfile.taskType === 'architecture_design') {
    if (!/interface|schema|api|pattern|boundary|contract/i.test(userPrompt)) {
      capabilityGapBefore += 25;
      missingContext.push('Architecture design prompt missing explicit boundary / contract requirements.');
    }
  } else if (taskProfile.taskType === 'refactoring') {
    if (!/test|spec|verify|benchmark/i.test(userPrompt)) {
      capabilityGapBefore += 20;
      missingContext.push('Refactoring prompt missing verification test criteria or regression safeguards.');
    }
  }

  // 3. Recall relevant critical memories from persistent memory store
  const relevantMemories = await recallMemory(userPrompt, workspaceRoot, { limit: 5 });

  // 4. Identify potential file paths mentioned in prompt and verify on disk
  const pathMatches = userPrompt.match(/[\w/.-]+\.(?:ts|js|py|go|rs|json|md|sql|html|css)/gi) || [];
  const verifiedFileContexts: { path: string; summary: string }[] = [];

  for (const rawMatch of pathMatches) {
    const candidatePath = path.isAbsolute(rawMatch) ? rawMatch : path.join(workspaceRoot, rawMatch);
    try {
      const stats = await fs.stat(candidatePath);
      if (stats.isFile()) {
        if (!suggestedFiles.includes(rawMatch)) {
          suggestedFiles.push(rawMatch);
        }
        // Extract top-level exports/signatures from real file
        const content = await fs.readFile(candidatePath, 'utf-8');
        const lines = content.split('\n').slice(0, 30);
        const sigs = lines.filter(l => /^(?:export|class|function|interface|type|const|let|var)\s/.test(l.trim()));
        if (sigs.length > 0) {
          verifiedFileContexts.push({
            path: rawMatch,
            summary: sigs.slice(0, 5).join('\n')
          });
        }
      }
    } catch {
      // File path in prompt does not exist on disk
      warnings.push(`Mentioned file "${rawMatch}" was not found on disk.`);
    }
  }

  if (suggestedFiles.length === 0) {
    capabilityGapBefore += 15;
    missingContext.push('No target workspace files explicitly referenced in user prompt.');
  }

  capabilityGapBefore = Math.min(100, capabilityGapBefore);

  // 5. Construct Enriched Prompt with Real Context
  let equalizationApplied = false;

  if (relevantMemories.length > 0) {
    equalizationApplied = true;
    contextAdditions.push('### Recalled Architectural Context & Constraints:');
    for (const mem of relevantMemories) {
      contextAdditions.push(`- **[${mem.category.toUpperCase()}] ${mem.title}**: ${mem.content}`);
    }
  }

  if (verifiedFileContexts.length > 0) {
    equalizationApplied = true;
    contextAdditions.push('### Workspace Target File Signatures:');
    for (const fileCtx of verifiedFileContexts) {
      contextAdditions.push(`#### \`${fileCtx.path}\` Key Signatures:\n\`\`\`typescript\n${fileCtx.summary}\n\`\`\``);
    }
  }

  if (missingContext.length > 0) {
    equalizationApplied = true;
    contextAdditions.push('### Detected Context Gaps & Equalization Guidelines:');
    for (const gap of missingContext) {
      contextAdditions.push(`- **[ATTENTION]**: ${gap}`);
    }
  }

  let enrichedPrompt = userPrompt;
  if (equalizationApplied && contextAdditions.length > 0) {
    enrichedPrompt = `${userPrompt}\n\n---\n[SHANAXON CONTEXT EQUALIZER AUTOMATIC AUGMENTATION]\n${contextAdditions.join('\n')}\n---`;
  }

  // Calculate Final Capability Gap after Equalization
  let capabilityGapAfter = capabilityGapBefore;
  if (equalizationApplied) {
    // Each recalled memory reduces gap by 15%
    capabilityGapAfter -= relevantMemories.length * 15;
    // Verified files reduce gap by 20%
    capabilityGapAfter -= verifiedFileContexts.length * 20;
    // Missing context guidelines reduce gap by 10%
    if (missingContext.length > 0) capabilityGapAfter -= 10;
  }

  capabilityGapAfter = Math.max(0, Math.round(capabilityGapAfter));

  return {
    originalPrompt: userPrompt,
    enrichedPrompt,
    injectedMemories: relevantMemories,
    suggestedFiles,
    missingContext,
    warnings,
    equalizationApplied,
    capabilityGapBefore,
    capabilityGapAfter
  };
}

import { ContextImportanceResult, ContextItem, ContextItemDisposition, EvidenceType, MemoryEntry, TaskProfile } from '../types';

export interface RawContextInput {
  id: string;
  category: 'architecture' | 'code' | 'memory' | 'history' | 'schema' | 'dependency';
  sourcePath?: string;
  rawContent: string;
  mtimeMs?: number;
  graphScore?: number;
  metadata?: Record<string, any>;
}

/**
 * Calculates composite relevance score of text content against a set of keywords and query terms.
 */
function calculateTextRelevance(content: string, terms: string[]): number {
  if (terms.length === 0 || !content) return 0.5;
  const contentLower = content.toLowerCase();
  let matches = 0;

  for (const term of terms) {
    if (contentLower.includes(term.toLowerCase())) {
      matches++;
    }
  }

  const ratio = matches / terms.length;
  return Math.min(1.0, 0.2 + ratio * 0.8);
}

export interface ImportanceScoringWeights {
  taskRelevance: number;      // default 0.40
  graphCentrality: number;    // default 0.25
  semanticSimilarity: number; // default 0.20
  recency: number;            // default 0.10
  memoryBoost: number;        // default 0.05
}

/**
 * Computes exact importance scores and assigns tier dispositions for all candidate context items.
 */
export function scoreContextImportance(
  userPrompt: string,
  rawItems: RawContextInput[],
  taskProfile: TaskProfile,
  graphCentralityMap: Record<string, number> = {},
  criticalMemories: MemoryEntry[] = [],
  customWeights?: Partial<ImportanceScoringWeights>
): ContextImportanceResult {
  const weights: ImportanceScoringWeights = {
    taskRelevance: customWeights?.taskRelevance ?? 0.40,
    graphCentrality: customWeights?.graphCentrality ?? 0.25,
    semanticSimilarity: customWeights?.semanticSimilarity ?? 0.20,
    recency: customWeights?.recency ?? 0.10,
    memoryBoost: customWeights?.memoryBoost ?? 0.05
  };
  const queryTerms = userPrompt.toLowerCase().split(/\W+/).filter(t => t.length > 2);
  const now = Date.now();

  const memorySourcePaths = new Set(
    criticalMemories.flatMap(m => [m.title, m.content]).join(' ').match(/[\w/-]+\.\w+/g) || []
  );

  const items: ContextItem[] = rawItems.map(item => {
    // 1. Task Relevance (weight: 0.40)
    const taskRelevance = calculateTextRelevance(
      item.rawContent,
      [...queryTerms, ...taskProfile.detectedKeywords]
    );

    // 2. Graph Centrality (weight: 0.25)
    let graphCentrality = item.graphScore ?? 0;
    if (item.sourcePath && graphCentralityMap[item.sourcePath] !== undefined) {
      graphCentrality = graphCentralityMap[item.sourcePath];
    }
    graphCentrality = Math.min(1.0, Math.max(0.0, graphCentrality));

    // 3. Semantic Similarity / Keyword Match (weight: 0.20)
    const semanticSimilarity = calculateTextRelevance(item.rawContent, queryTerms);

    // 4. Recency (weight: 0.10)
    let recency = 0.5;
    if (item.mtimeMs) {
      const ageHours = (now - item.mtimeMs) / (1000 * 60 * 60);
      if (ageHours < 1) recency = 1.0;
      else if (ageHours < 24) recency = 0.8;
      else if (ageHours < 168) recency = 0.6;
      else recency = 0.3;
    }

    // 5. Memory Boost (weight: 0.05)
    let memoryBoost = 0.0;
    if (item.category === 'memory') {
      memoryBoost = 1.0;
    } else if (item.sourcePath && memorySourcePaths.has(item.sourcePath)) {
      memoryBoost = 0.8;
    }

    // Composite importance score
    const importanceScore = Number((
      weights.taskRelevance * taskRelevance +
      weights.graphCentrality * graphCentrality +
      weights.semanticSimilarity * semanticSimilarity +
      weights.recency * recency +
      weights.memoryBoost * memoryBoost
    ).toFixed(4));

    // Determine disposition
    let disposition: ContextItemDisposition = 'normal';
    if (importanceScore >= 0.75 || memoryBoost >= 0.8 || graphCentrality >= 0.85) {
      disposition = 'must_include';
    } else if (importanceScore >= 0.50) {
      disposition = 'normal';
    } else if (importanceScore >= 0.25) {
      disposition = 'summarize';
    } else {
      disposition = 'omit';
    }

    // Determine evidence type tag
    let evidenceType: EvidenceType = 'known_fact';
    if (item.category === 'memory') {
      evidenceType = 'known_fact';
    } else if (item.category === 'dependency') {
      evidenceType = 'inferred_fact';
    } else if (importanceScore < 0.35) {
      evidenceType = 'uncertain_assumption';
    }

    return {
      id: item.id,
      category: item.category,
      sourcePath: item.sourcePath,
      rawContent: item.rawContent,
      importanceScore,
      scoreBreakdown: {
        taskRelevance: Number(taskRelevance.toFixed(3)),
        graphCentrality: Number(graphCentrality.toFixed(3)),
        semanticSimilarity: Number(semanticSimilarity.toFixed(3)),
        recency: Number(recency.toFixed(3)),
        memoryBoost: Number(memoryBoost.toFixed(3))
      },
      disposition,
      evidenceType,
      metadata: item.metadata
    };
  });

  // Sort items descending by importance score
  items.sort((a, b) => b.importanceScore - a.importanceScore);

  const totalItems = items.length;
  const topItemsCount = items.filter(i => i.disposition === 'must_include' || i.disposition === 'normal').length;
  const avgImportance = totalItems > 0 
    ? items.reduce((acc, i) => acc + i.importanceScore, 0) / totalItems 
    : 0;

  return {
    items,
    totalItems,
    topItemsCount,
    averageImportance: Number(avgImportance.toFixed(4))
  };
}

import { promises as fs } from 'fs';
import * as path from 'path';
import { CriticalMemoryState, MemoryCategory, MemoryEntry } from '../types';
import { getConfig } from '../core/configLoader';
import { resolveTenantContext } from '../security/tenantIsolation';

const stateCache = new Map<string, CriticalMemoryState>();
const writeQueues = new Map<string, Promise<void>>();

function generateId(): string {
  return `mem_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`;
}

function enqueueMemoryWrite(filePath: string, task: () => Promise<void>): Promise<void> {
  const prev = writeQueues.get(filePath) || Promise.resolve();
  const next = prev.catch(() => {}).then(task);
  writeQueues.set(filePath, next);
  return next;
}

/**
 * Resolves the absolute path to the memory JSON storage file.
 */
function resolveMemoryPath(workspaceRoot: string): string {
  const config = getConfig();
  const tenant = resolveTenantContext(config, workspaceRoot);
  const relPath = config.memoryPath || '.shanaxon/memory.json';
  if (tenant.tenantId === 'local' && tenant.organizationId === 'default') {
    return path.resolve(workspaceRoot, relPath);
  }
  const dir = path.dirname(relPath);
  const ext = path.extname(relPath);
  const baseName = path.basename(relPath, ext);
  const scopedFileName = `${baseName}_${tenant.tenantId}_${tenant.organizationId}${ext}`;
  return path.resolve(workspaceRoot, dir, scopedFileName);
}

/**
 * Loads the critical memory state from disk.
 */
export async function loadMemory(workspaceRoot: string): Promise<CriticalMemoryState> {
  const filePath = resolveMemoryPath(workspaceRoot);

  const cached = stateCache.get(filePath);
  if (cached) {
    return cached;
  }

  try {
    const raw = await fs.readFile(filePath, 'utf-8');
    const parsed = JSON.parse(raw) as CriticalMemoryState;
    stateCache.set(filePath, parsed);
    return parsed;
  } catch {
    const emptyState: CriticalMemoryState = {
      entries: [],
      version: 1,
      lastModified: new Date().toISOString()
    };
    stateCache.set(filePath, emptyState);
    return emptyState;
  }
}

/**
 * Flushes memory state atomically to disk, serialized per memory file path.
 */
async function saveMemory(state: CriticalMemoryState, workspaceRoot: string): Promise<void> {
  const filePath = resolveMemoryPath(workspaceRoot);

  await enqueueMemoryWrite(filePath, async () => {
    const dir = path.dirname(filePath);
    await fs.mkdir(dir, { recursive: true });

    state.lastModified = new Date().toISOString();
    stateCache.set(filePath, state);

    const tempPath = `${filePath}.${Date.now()}.${Math.random().toString(36).substring(2, 7)}.tmp`;
    try {
      await fs.writeFile(tempPath, JSON.stringify(state, null, 2), 'utf-8');
      await fs.rename(tempPath, filePath);
    } catch (err) {
      await fs.unlink(tempPath).catch(() => {});
      throw err;
    }
  });
}

/**
 * Stores a new architectural decision, constraint, dependency, or gotcha in critical memory.
 */
export async function storeMemory(
  entry: Omit<MemoryEntry, 'id' | 'createdAt' | 'updatedAt'>,
  workspaceRoot: string
): Promise<MemoryEntry> {
  const config = getConfig();
  const tenant = resolveTenantContext(config, workspaceRoot);
  const state = await loadMemory(workspaceRoot);

  const now = new Date().toISOString();
  const newEntry: MemoryEntry = {
    ...entry,
    id: generateId(),
    createdAt: now,
    updatedAt: now,
    tenantId: tenant.tenantId,
    workspaceId: tenant.workspaceId
  };

  // Check if duplicate entry (same category, title, and content) exists to update
  const existingIdx = state.entries.findIndex(
    e => e.category === entry.category && e.title.toLowerCase() === entry.title.toLowerCase() && e.content.toLowerCase() === entry.content.toLowerCase()
  );

  if (existingIdx >= 0) {
    newEntry.id = state.entries[existingIdx].id;
    newEntry.createdAt = state.entries[existingIdx].createdAt;
    state.entries[existingIdx] = newEntry;
  } else {
    state.entries.unshift(newEntry);
  }

  // Enforce rotation limit
  const maxLimit = config.maxMemoryEntries || 500;
  if (state.entries.length > maxLimit) {
    state.entries = state.entries.slice(0, maxLimit);
  }

  await saveMemory(state, workspaceRoot);
  return newEntry;
}

/**
 * Recalls relevant memories matching a natural language prompt or query.
 */
export async function recallMemory(
  query: string,
  workspaceRoot: string,
  options?: { category?: MemoryCategory; limit?: number }
): Promise<MemoryEntry[]> {
  const state = await loadMemory(workspaceRoot);
  let candidates = state.entries;

  const nowMs = Date.now();
  const thirtyDaysMs = 30 * 24 * 60 * 60 * 1000;
  let metadataDirty = false;

  // Mark staleness and contradiction
  for (let i = 0; i < candidates.length; i++) {
    const entry = candidates[i];
    const ageMs = nowMs - new Date(entry.updatedAt).getTime();
    if (ageMs > thirtyDaysMs && entry.isStale !== true) {
      entry.isStale = true;
      metadataDirty = true;
    }

    // Check for contradictions with newer entries in same category
    for (let j = 0; j < candidates.length; j++) {
      if (i === j) continue;
      const other = candidates[j];
      if (other.category === entry.category) {
        const entryTime = new Date(entry.createdAt || entry.updatedAt).getTime();
        const otherTime = new Date(other.createdAt || other.updatedAt).getTime();
        const isOtherNewer = (otherTime > entryTime) || (otherTime === entryTime && j < i);
        const negRegex = /\b(no|not|never|don't|do not|cannot|shouldn't|avoid)\b/i;
        const titleOverlap = other.title.toLowerCase() === entry.title.toLowerCase() ||
          other.title.toLowerCase().split(/\s+/).some(w => w.length > 3 && entry.title.toLowerCase().includes(w));
        const hasOpposingNegation =
          (negRegex.test(other.content) && !negRegex.test(entry.content)) ||
          (!negRegex.test(other.content) && negRegex.test(entry.content));

        if (isOtherNewer && titleOverlap && hasOpposingNegation && entry.contradictedBy !== other.id) {
          entry.contradictedBy = other.id;
          metadataDirty = true;
        }
      }
    }
  }

  if (metadataDirty) {
    await saveMemory(state, workspaceRoot);
  }

  if (options?.category) {
    candidates = candidates.filter(e => e.category === options.category);
  }

  if (!query || query.trim().length === 0) {
    return candidates.slice(0, options?.limit || 10);
  }

  const queryTerms = query.toLowerCase().split(/\W+/).filter(t => t.length > 2);

  const scored = candidates.map(entry => {
    let score = 0;
    const titleLower = entry.title.toLowerCase();
    const contentLower = entry.content.toLowerCase();
    const tagsLower = entry.tags.map(t => t.toLowerCase());

    for (const term of queryTerms) {
      if (titleLower.includes(term)) score += 3.0;
      if (contentLower.includes(term)) score += 1.0;
      if (tagsLower.some(t => t.includes(term))) score += 2.0;
    }

    if (entry.priority === 'high') score *= 1.5;
    if (entry.priority === 'medium') score *= 1.2;
    if (entry.isStale) score *= 0.8; // Slight penalty for stale memories
    if (entry.contradictedBy) score *= 0.5; // Significant penalty for contradicted memories

    return { entry, score };
  });

  const filtered = scored.filter(s => s.score > 0);
  filtered.sort((a, b) => b.score - a.score);

  const limit = options?.limit || 10;
  return filtered.slice(0, limit).map(s => s.entry);
}

/**
 * Lists memories in the system, optionally filtered by category.
 */
export async function listMemory(
  workspaceRoot: string,
  category?: MemoryCategory
): Promise<MemoryEntry[]> {
  const state = await loadMemory(workspaceRoot);
  if (category) {
    return state.entries.filter(e => e.category === category);
  }
  return state.entries;
}

/**
 * Deletes a memory entry by ID.
 */
export async function deleteMemory(
  id: string,
  workspaceRoot: string
): Promise<boolean> {
  const state = await loadMemory(workspaceRoot);
  const initialCount = state.entries.length;
  state.entries = state.entries.filter(e => e.id !== id);

  if (state.entries.length !== initialCount) {
    await saveMemory(state, workspaceRoot);
    return true;
  }
  return false;
}

/**
 * Resets memory state in memory (for test isolation).
 */
export function resetMemoryState(): void {
  stateCache.clear();
}

import {
  CompressionTier,
  EconomicEvaluation,
  OptimizationReceipt,
  TaskProfile,
  WorkspaceConfig,
} from '../types';
import { Tokenizer } from '../core/tokenizer';
import { analyzeBaseline } from './baselineAnalyzer';
import { shouldAttemptOptimization, PreflightDecision } from './economicPreflight';
import { evaluateParetoTradeoff, OptimizationCandidate } from './paretoSelector';
import { evaluateEconomicGate } from './economicGate';
import { calculateModelCost, calculateOptimizerCost, ModelPricingRegistry } from './economicsEngine';
import { AttemptTracker } from './attemptTracker';
import { evaluateQualityGate, QualityGateResult } from './qualityGate';
import { adjustTierForModel } from './modelPolicy';
import { createOptimizationReceipt } from './optimizationMetadata';

export type OptimizableTier = 'normal' | 'medium' | 'aggressive';

export interface EconomicDecisionInput {
  workspaceRoot: string;
  config: WorkspaceConfig;
  activeModel?: string;
  baselineText: string;
  filePath?: string;
  candidateOutputs: Partial<Record<OptimizableTier, string>>;
  qualityScores?: Partial<Record<OptimizableTier, QualityGateResult>>;
  taskProfile?: TaskProfile;
  optimizerDurationMs: number;
  sessionId?: string;
  taskId?: string;
  itemsIncluded?: number;
  itemsSummarized?: number;
  itemsOmitted?: number;
  evidenceCompleteness?: number;
}

export interface EconomicDecisionOutput {
  decision: 'OPTIMIZE' | 'FALLBACK_BASELINE';
  selectedTier: OptimizableTier;
  outputText: string;
  receipt: OptimizationReceipt;
  preflight?: PreflightDecision;
  economicEvaluation?: EconomicEvaluation;
  qualityScore: number;
  qualityPassed: boolean;
  warnings: string[];
}

const DEFAULT_TASK_PROFILE: TaskProfile = {
  taskType: 'unknown',
  complexityScore: 0.5,
  confidence: 0.5,
  detectedKeywords: [],
  recommendedBudgetMultiplier: 1.0,
  minRetentionThreshold: 0.85,
  reasoning: 'Default fallback task profile',
};

/**
 * Resolves the effective pricing model name by preferring activeModel if known in ModelPricingRegistry,
 * otherwise falling back to config.pricingModel.
 */
function resolvePricingModel(activeModel: string | undefined, config: WorkspaceConfig): string {
  const registry = ModelPricingRegistry.getInstance();
  const primary = activeModel || config.activeModel || config.pricingModel || 'claude-3-7-sonnet';
  if (registry.getPricingStatus(undefined, primary) === 'KNOWN') {
    return primary;
  }
  if (config.pricingModel && registry.getPricingStatus(undefined, config.pricingModel) === 'KNOWN') {
    return config.pricingModel;
  }
  return primary;
}

/**
 * Shared v6.1 Economic Decision Pipeline used by live MCP tool handlers.
 * Runs baseline cost analysis, preflight abstention, quality gate scoring,
 * Pareto tier selection, optimizer overhead & retry accounting, and the Economic Gate.
 */
export function evaluateEconomicDecision(input: EconomicDecisionInput): EconomicDecisionOutput {
  const {
    config,
    baselineText,
    filePath,
    candidateOutputs,
    qualityScores,
    optimizerDurationMs,
    sessionId,
    taskId,
  } = input;

  const econConfig = config.economics;
  const minSavingsUsd = econConfig?.minimumSavingsUsd ?? 0.00001;
  const minSavingsPercent = econConfig?.minimumSavingsPercent ?? 2.0;
  const qualityFloor = econConfig?.qualityFloor ?? config.qualityGateMinRetention ?? 0.85;
  const enablePreflight = econConfig?.enablePreflight !== false;
  const trackRetries = econConfig?.trackRetries !== false;
  const costPerSec =
    econConfig?.optimizerCostPerSecond ??
    (econConfig?.optimizerComputeCostPerMs !== undefined
      ? econConfig.optimizerComputeCostPerMs * 1000
      : 0.001);

  const model = resolvePricingModel(input.activeModel, config);
  const taskProfile = input.taskProfile || {
    ...DEFAULT_TASK_PROFILE,
    minRetentionThreshold: qualityFloor,
  };

  // 1. Baseline token count & USD cost
  const baselineInputTokens = Tokenizer.countTokens(baselineText, filePath);
  const baselineAnalysis = analyzeBaseline({
    model,
    originalCode: baselineText,
    filePath,
    explicitInputTokens: baselineInputTokens,
  });

  // 2. Preflight check
  let preflight: PreflightDecision | undefined;
  if (enablePreflight) {
    preflight = shouldAttemptOptimization({
      baselineInputTokens,
      model,
      estimatedOptimizerLatencyMs: Math.max(1, Math.round(optimizerDurationMs)),
      minimumSavingsUsd: minSavingsUsd,
      minimumSavingsPercent: minSavingsPercent,
    });

    if (!preflight.shouldOptimize) {
      const preflightWarnings = [preflight.reason];
      const receipt = createOptimizationReceipt({
        timestamp: new Date().toISOString(),
        taskId,
        taskType: taskProfile.taskType,
        model,
        originalTokenEstimate: baselineInputTokens,
        finalTokenEstimate: baselineInputTokens,
        compressionRatio: 1.0,
        savingsPct: 0,
        qualityGatePassed: true,
        qualityScore: 1.0,
        evidenceCompleteness: input.evidenceCompleteness ?? 1.0,
        itemsIncluded: input.itemsIncluded ?? 1,
        itemsSummarized: input.itemsSummarized ?? 0,
        itemsOmitted: input.itemsOmitted ?? 0,
        executionTimeMs: Math.round(optimizerDurationMs),
        warnings: preflightWarnings,
        baselineTotalCost: baselineAnalysis.breakdown.totalCost,
        tokenistTotalCost: baselineAnalysis.breakdown.totalCost,
        absoluteSavings: 0,
        optimizerCost: 0,
        isEconomicallyEffective: false,
        economics: {
          optimizationDecision: 'ABSTAINED',
          decisionReason: preflight.reason,
        },
      });

      return {
        decision: 'FALLBACK_BASELINE',
        selectedTier: 'normal',
        outputText: baselineText,
        receipt,
        preflight,
        qualityScore: 1.0,
        qualityPassed: true,
        warnings: preflightWarnings,
      };
    }
  }

  // 3. Optimizer overhead & retry cost
  const optimizerCost = calculateOptimizerCost({
    latencyMs: Math.max(0, optimizerDurationMs),
    mode: econConfig?.optimizerCostMode ?? 'estimated',
    configuredRateMs: costPerSec / 1000,
  });

  const retryKey = taskId || sessionId;
  const retryCost = trackRetries && retryKey ? AttemptTracker.getInstance().calculateRetryCost(retryKey) : 0;

  // 4. Score quality & build Pareto candidates across model-policy-allowed tiers
  const tiers: OptimizableTier[] = ['normal', 'medium', 'aggressive'];
  const candidates: OptimizationCandidate[] = [];
  const qualityMap = new Map<OptimizableTier, QualityGateResult>();
  const allWarnings: string[] = [];

  for (const tier of tiers) {
    const candidateText = candidateOutputs[tier];
    if (candidateText === undefined) continue;

    // Enforce ModelPolicy maxAllowedTier
    if (adjustTierForModel(tier as CompressionTier, model) !== tier) {
      continue;
    }

    let qg: QualityGateResult;
    if (qualityScores?.[tier]) {
      qg = qualityScores[tier]!;
    } else if (config.enableQualityGate === false) {
      qg = {
        passed: true,
        score: 1.0,
        retentionPct: 100,
        warnings: [],
        reason: 'Quality gate disabled in config.',
        signals: {
          symbolScore: 1.0,
          dependencyScore: 1.0,
          signatureScore: 1.0,
          constraintCommentScore: 1.0,
        },
      };
    } else {
      qg = evaluateQualityGate(baselineText, candidateText, taskProfile, tier, qualityFloor);
    }

    qualityMap.set(tier, qg);
    if (qg.warnings.length > 0) {
      allWarnings.push(...qg.warnings);
    }

    const candTokens = Tokenizer.countTokens(candidateText, filePath);
    const estOutputTokens = baselineAnalysis.outputTokens;
    const candModelCost = calculateModelCost({
      model,
      inputTokens: candTokens,
      outputTokens: estOutputTokens,
    });

    const criticalLoss = qg.warnings.some((w) => w.includes('CRITICAL')) ? 1 : 0;

    candidates.push({
      tier,
      inputTokens: candTokens,
      estimatedOutputTokens: estOutputTokens,
      qualityScore: qg.score,
      criticalInformationLoss: criticalLoss,
      dependencyRetention: qg.signals?.dependencyScore ?? 1.0,
      symbolRetention: qg.signals?.symbolScore ?? 1.0,
      evidenceCoverage: input.evidenceCompleteness ?? 1.0,
      estimatedModelCost: candModelCost.totalCost,
      optimizerCost: optimizerCost.cost,
      totalProjectedCost: parseFloat((candModelCost.totalCost + optimizerCost.cost + retryCost).toFixed(6)),
      warnings: qg.warnings,
      compressedContent: candidateText,
    });
  }

  // 5. Pareto tradeoff selection
  const pareto = evaluateParetoTradeoff({
    candidates,
    qualityFloor,
  });

  for (const rej of pareto.rejectedCandidates) {
    allWarnings.push(`[Pareto rejected ${rej.candidate.tier}] ${rej.reason}`);
  }

  // 6. Economic Gate evaluation
  const economicEvaluation = evaluateEconomicGate({
    baseline: baselineAnalysis.breakdown,
    selectedCandidate: pareto.selectedCandidate,
    optimizer: optimizerCost,
    minimumSavingsUsd: minSavingsUsd,
    minimumSavingsPercent: minSavingsPercent,
    retryCost,
    qualityRiskFailed: pareto.selectedCandidate === null,
  });

  if (
    economicEvaluation.decision !== 'OPTIMIZE' ||
    !pareto.selectedCandidate ||
    pareto.selectedCandidate.compressedContent === undefined
  ) {
    const fallbackWarnings = Array.from(new Set([...allWarnings, economicEvaluation.reason]));
    const receipt = createOptimizationReceipt({
      timestamp: new Date().toISOString(),
      taskId,
      taskType: taskProfile.taskType,
      model,
      originalTokenEstimate: baselineInputTokens,
      finalTokenEstimate: baselineInputTokens,
      compressionRatio: 1.0,
      savingsPct: 0,
      qualityGatePassed: pareto.selectedCandidate !== null,
      qualityScore: pareto.selectedCandidate?.qualityScore ?? 1.0,
      evidenceCompleteness: input.evidenceCompleteness ?? 1.0,
      itemsIncluded: input.itemsIncluded ?? 1,
      itemsSummarized: input.itemsSummarized ?? 0,
      itemsOmitted: input.itemsOmitted ?? 0,
      executionTimeMs: Math.round(optimizerDurationMs),
      warnings: fallbackWarnings,
      baselineTotalCost: economicEvaluation.baselineTotalCost,
      tokenistTotalCost: economicEvaluation.baselineTotalCost,
      absoluteSavings: 0,
      optimizerCost: optimizerCost.cost,
      isEconomicallyEffective: false,
      economics: {
        projected: economicEvaluation,
        actual: economicEvaluation,
        optimizationDecision: 'BASELINE',
        decisionReason: economicEvaluation.reason,
      },
    });

    return {
      decision: 'FALLBACK_BASELINE',
      selectedTier: 'normal',
      outputText: baselineText,
      receipt,
      preflight,
      economicEvaluation,
      qualityScore: receipt.qualityScore,
      qualityPassed: receipt.qualityGatePassed,
      warnings: fallbackWarnings,
    };
  }

  const selectedTier = pareto.selectedCandidate.tier as OptimizableTier;
  const selectedText = pareto.selectedCandidate.compressedContent;
  const finalTokens = pareto.selectedCandidate.inputTokens;
  const selectedQuality = qualityMap.get(selectedTier);

  const compressionRatio = finalTokens > 0 ? parseFloat((baselineInputTokens / finalTokens).toFixed(2)) : 1.0;
  const savingsPct =
    baselineInputTokens > 0
      ? parseFloat((((baselineInputTokens - finalTokens) / baselineInputTokens) * 100).toFixed(2))
      : 0;

  const receipt = createOptimizationReceipt({
    timestamp: new Date().toISOString(),
    taskId,
    taskType: taskProfile.taskType,
    model,
    originalTokenEstimate: baselineInputTokens,
    finalTokenEstimate: finalTokens,
    compressionRatio,
    savingsPct,
    qualityGatePassed: selectedQuality ? selectedQuality.passed : true,
    qualityScore: selectedQuality ? selectedQuality.score : pareto.selectedCandidate.qualityScore,
    evidenceCompleteness: input.evidenceCompleteness ?? 1.0,
    itemsIncluded: input.itemsIncluded ?? (selectedTier === 'normal' ? 1 : 0),
    itemsSummarized: input.itemsSummarized ?? (selectedTier === 'normal' ? 0 : 1),
    itemsOmitted: input.itemsOmitted ?? 0,
    executionTimeMs: Math.round(optimizerDurationMs),
    warnings: Array.from(new Set(allWarnings)),
    baselineTotalCost: economicEvaluation.baselineTotalCost,
    tokenistTotalCost: economicEvaluation.tokenistTotalCost,
    absoluteSavings: economicEvaluation.absoluteSavings,
    optimizerCost: optimizerCost.cost,
    isEconomicallyEffective: true,
    economics: {
      projected: economicEvaluation,
      actual: economicEvaluation,
      optimizationDecision: 'OPTIMIZED',
      decisionReason: economicEvaluation.reason,
    },
  });

  return {
    decision: 'OPTIMIZE',
    selectedTier,
    outputText: selectedText,
    receipt,
    preflight,
    economicEvaluation,
    qualityScore: receipt.qualityScore,
    qualityPassed: receipt.qualityGatePassed,
    warnings: receipt.warnings,
  };
}

import { CostBreakdown, EconomicEvaluation, OptimizerCost } from '../types';
import { OptimizationCandidate } from './paretoSelector';

export interface EvaluateEconomicGateOptions {
  baseline: CostBreakdown;
  selectedCandidate: OptimizationCandidate | null;
  optimizer: OptimizerCost;
  minimumSavingsUsd?: number;
  minimumSavingsPercent?: number;
  retryCost?: number;
  qualityRiskFailed?: boolean;
  criticalLossFailed?: boolean;
}

/**
 * Evaluates whether an optimization candidate is economically beneficial compared to the baseline.
 * Enforces hard rules: quality checks, minimum savings thresholds, optimizer overhead inclusion, and retry costs.
 */
export function evaluateEconomicGate(options: EvaluateEconomicGateOptions): EconomicEvaluation {
  const minSavingsUsd = options.minimumSavingsUsd ?? 0.00001;
  const minSavingsPct = options.minimumSavingsPercent ?? 2.0;
  const retryCost = options.retryCost || 0;

  const baselineTotalCost = parseFloat(options.baseline.totalCost.toFixed(6));

  if (options.criticalLossFailed) {
    return createEvaluation({
      baseline: options.baseline,
      optimized: emptyBreakdown(),
      optimizer: options.optimizer,
      baselineTotalCost,
      tokenistTotalCost: baselineTotalCost,
      absoluteSavings: 0,
      savingsPercent: 0,
      isEconomicallyEffective: false,
      decision: 'FALLBACK_BASELINE',
      reason: 'CRITICAL_INFORMATION_LOSS',
    });
  }

  if (options.qualityRiskFailed || !options.selectedCandidate) {
    return createEvaluation({
      baseline: options.baseline,
      optimized: emptyBreakdown(),
      optimizer: options.optimizer,
      baselineTotalCost,
      tokenistTotalCost: baselineTotalCost,
      absoluteSavings: 0,
      savingsPercent: 0,
      isEconomicallyEffective: false,
      decision: 'FALLBACK_BASELINE',
      reason: 'QUALITY_RISK_TOO_HIGH',
    });
  }

  if (options.baseline.pricingStatus === 'PRICE_UNAVAILABLE') {
    return createEvaluation({
      baseline: options.baseline,
      optimized: {
        inputTokens: options.selectedCandidate.inputTokens,
        outputTokens: options.selectedCandidate.estimatedOutputTokens || 0,
        inputCost: 0,
        outputCost: 0,
        retryCost: 0,
        totalCost: 0,
        pricingStatus: 'PRICE_UNAVAILABLE',
      },
      optimizer: options.optimizer,
      baselineTotalCost: 0,
      tokenistTotalCost: 0,
      absoluteSavings: 0,
      savingsPercent: 0,
      isEconomicallyEffective: false,
      decision: 'INSUFFICIENT_PRICING_DATA',
      reason: 'UNKNOWN_MODEL_PRICING',
    });
  }

  const optimizedModelCost = options.selectedCandidate.estimatedModelCost;
  const tokenistTotalCost = parseFloat((optimizedModelCost + options.optimizer.cost + retryCost).toFixed(6));
  const absoluteSavings = parseFloat((baselineTotalCost - tokenistTotalCost).toFixed(6));
  const savingsPercent = baselineTotalCost > 0 ? parseFloat(((absoluteSavings / baselineTotalCost) * 100).toFixed(2)) : 0;

  const optimizedBreakdown: CostBreakdown = {
    inputTokens: options.selectedCandidate.inputTokens,
    outputTokens: options.selectedCandidate.estimatedOutputTokens || 0,
    inputCost: parseFloat((options.selectedCandidate.estimatedModelCost * 0.7).toFixed(6)), // approx breakdown
    outputCost: parseFloat((options.selectedCandidate.estimatedModelCost * 0.3).toFixed(6)),
    retryCost,
    totalCost: tokenistTotalCost,
    pricingStatus: 'KNOWN',
  };

  // Check retry cost explicitly
  if (retryCost > 0 && retryCost >= (baselineTotalCost - (optimizedModelCost + options.optimizer.cost))) {
    return createEvaluation({
      baseline: options.baseline,
      optimized: optimizedBreakdown,
      optimizer: options.optimizer,
      baselineTotalCost,
      tokenistTotalCost,
      absoluteSavings,
      savingsPercent,
      isEconomicallyEffective: false,
      decision: 'FALLBACK_BASELINE',
      reason: 'RETRY_COST_EXCEEDED_SAVINGS',
    });
  }

  // Check total cost vs baseline
  if (tokenistTotalCost >= baselineTotalCost) {
    let reason: EconomicEvaluation['reason'] = 'NO_MEANINGFUL_SAVINGS';
    if (optimizedModelCost < options.baseline.totalCost && tokenistTotalCost >= baselineTotalCost) {
      reason = 'OPTIMIZATION_OVERHEAD_TOO_HIGH';
    } else if (baselineTotalCost > 0 && Math.abs(absoluteSavings) < 0.0001) {
      reason = 'BASELINE_ALREADY_OPTIMAL';
    }

    return createEvaluation({
      baseline: options.baseline,
      optimized: optimizedBreakdown,
      optimizer: options.optimizer,
      baselineTotalCost,
      tokenistTotalCost,
      absoluteSavings,
      savingsPercent,
      isEconomicallyEffective: false,
      decision: 'FALLBACK_BASELINE',
      reason,
    });
  }

  // Check minimum meaningful savings threshold
  if (absoluteSavings < minSavingsUsd || savingsPercent < minSavingsPct) {
    return createEvaluation({
      baseline: options.baseline,
      optimized: optimizedBreakdown,
      optimizer: options.optimizer,
      baselineTotalCost,
      tokenistTotalCost,
      absoluteSavings,
      savingsPercent,
      isEconomicallyEffective: false,
      decision: 'FALLBACK_BASELINE',
      reason: 'NO_MEANINGFUL_SAVINGS',
    });
  }

  return createEvaluation({
    baseline: options.baseline,
    optimized: optimizedBreakdown,
    optimizer: options.optimizer,
    baselineTotalCost,
    tokenistTotalCost,
    absoluteSavings,
    savingsPercent,
    isEconomicallyEffective: true,
    decision: 'OPTIMIZE',
    reason: 'SAVINGS_ACCEPTED',
  });
}

function emptyBreakdown(): CostBreakdown {
  return {
    inputTokens: 0,
    outputTokens: 0,
    inputCost: 0,
    outputCost: 0,
    retryCost: 0,
    totalCost: 0,
    pricingStatus: 'PRICE_UNAVAILABLE',
  };
}

function createEvaluation(data: EconomicEvaluation): EconomicEvaluation {
  return {
    ...data,
    projectedSavings: data.absoluteSavings,
    projectedSavingsPercent: data.savingsPercent,
  };
}

import { calculateModelCost, calculateOptimizerCost, ModelPricingRegistry } from './economicsEngine';

export interface PreflightOptions {
  baselineInputTokens: number;
  model: string;
  provider?: string;
  estimatedCompressionRatio?: number; // e.g. 0.5 means 50% tokens remaining
  estimatedOptimizerLatencyMs?: number;
  minimumSavingsUsd?: number;
  minimumSavingsPercent?: number;
}

export interface PreflightDecision {
  shouldOptimize: boolean;
  projectedBaselineCost?: number;
  projectedOptimizedCost?: number;
  projectedOptimizerCost?: number;
  projectedSavings?: number;
  reason:
    | 'LIKELY_BENEFICIAL'
    | 'TOO_SMALL_REQUEST'
    | 'BASELINE_ALREADY_EFFICIENT'
    | 'PROJECTED_NEGATIVE_SAVINGS'
    | 'UNKNOWN_PRICING';
}

/**
 * Pre-evaluates whether optimization is likely to yield financial savings before running heavy AST compression.
 */
export function shouldAttemptOptimization(options: PreflightOptions): PreflightDecision {
  // Conservative threshold: Requests under 150 tokens are usually too small to benefit
  if (options.baselineInputTokens < 150) {
    return {
      shouldOptimize: false,
      reason: 'TOO_SMALL_REQUEST',
    };
  }

  const registry = ModelPricingRegistry.getInstance();
  const pricingStatus = registry.getPricingStatus(options.provider, options.model);

  if (pricingStatus === 'PRICE_UNAVAILABLE') {
    return {
      shouldOptimize: false,
      reason: 'UNKNOWN_PRICING',
    };
  }

  const estRatio = options.estimatedCompressionRatio ?? 0.5;
  const estLatency = options.estimatedOptimizerLatencyMs ?? 10;
  const minSavingsUsd = options.minimumSavingsUsd ?? 0.00001;
  const minSavingsPct = options.minimumSavingsPercent ?? 2.0;
  const estOutputTokens = Math.max(100, Math.ceil(options.baselineInputTokens * 0.05));

  const baselineEst = calculateModelCost({
    provider: options.provider,
    model: options.model,
    inputTokens: options.baselineInputTokens,
    outputTokens: estOutputTokens,
  });

  const optTokens = Math.ceil(options.baselineInputTokens * estRatio);
  const optimizedEst = calculateModelCost({
    provider: options.provider,
    model: options.model,
    inputTokens: optTokens,
    outputTokens: estOutputTokens,
  });

  const optimizerCostObj = calculateOptimizerCost({ latencyMs: estLatency });

  const projectedBaselineCost = baselineEst.totalCost;
  const projectedOptimizedCost = optimizedEst.totalCost;
  const projectedOptimizerCost = optimizerCostObj.cost;

  const totalTokenistCost = projectedOptimizedCost + projectedOptimizerCost;
  const projectedSavings = parseFloat((projectedBaselineCost - totalTokenistCost).toFixed(6));
  const projectedSavingsPct = projectedBaselineCost > 0 ? (projectedSavings / projectedBaselineCost) * 100 : 0;

  if (projectedSavings <= 0) {
    return {
      shouldOptimize: false,
      projectedBaselineCost,
      projectedOptimizedCost,
      projectedOptimizerCost,
      projectedSavings,
      reason: 'PROJECTED_NEGATIVE_SAVINGS',
    };
  }

  if (projectedSavings < minSavingsUsd || projectedSavingsPct < minSavingsPct) {
    return {
      shouldOptimize: false,
      projectedBaselineCost,
      projectedOptimizedCost,
      projectedOptimizerCost,
      projectedSavings,
      reason: 'BASELINE_ALREADY_EFFICIENT',
    };
  }

  return {
    shouldOptimize: true,
    projectedBaselineCost,
    projectedOptimizedCost,
    projectedOptimizerCost,
    projectedSavings,
    reason: 'LIKELY_BENEFICIAL',
  };
}

import * as fs from 'fs';
import * as path from 'path';
import { EconomicEvaluation, OptimizationReceipt } from '../types';

export interface CumulativeEconomics {
  baselineSpend: number;
  tokenistSpend: number;
  optimizerSpend: number;
  netSavings: number;
  savingsPercent: number;
  requestCount: number;
  optimizedRequestCount: number;
  abstainedRequestCount: number;
  economicallyEffectiveRate: number; // 0 - 100
  averageSavings: number;
  medianSavings: number;
  retryRate: number;
}

/**
 * Aggregates economic evaluations across requests for telemetry reporting and FinOps integration.
 * Supports disk persistence to .shanaxon/economics_ledger.json.
 */
export class EconomicsAggregator {
  private static instance: EconomicsAggregator;
  private records: OptimizationReceipt[] = [];
  private ledgerPath: string = path.resolve(process.cwd(), '.shanaxon', 'economics_ledger.json');

  private constructor() {
    this.loadFromDisk();
  }

  public static getInstance(): EconomicsAggregator {
    if (!EconomicsAggregator.instance) {
      EconomicsAggregator.instance = new EconomicsAggregator();
    }
    return EconomicsAggregator.instance;
  }

  public recordReceipt(receipt: OptimizationReceipt): void {
    this.records.push(receipt);
    this.persistToDisk();
  }

  public getSummary(): CumulativeEconomics {
    if (this.records.length === 0) {
      return {
        baselineSpend: 0,
        tokenistSpend: 0,
        optimizerSpend: 0,
        netSavings: 0,
        savingsPercent: 0,
        requestCount: 0,
        optimizedRequestCount: 0,
        abstainedRequestCount: 0,
        economicallyEffectiveRate: 0,
        averageSavings: 0,
        medianSavings: 0,
        retryRate: 0,
      };
    }

    let baselineSpend = 0;
    let tokenistSpend = 0;
    let optimizerSpend = 0;
    let optimizedCount = 0;
    let abstainedCount = 0;
    let effectiveCount = 0;
    const savingsList: number[] = [];
    let retryCount = 0;

    for (const r of this.records) {
      const bCost = r.baselineTotalCost || 0;
      const tCost = r.tokenistTotalCost || 0;
      const optCost = r.optimizerCost || 0;
      const savings = r.absoluteSavings || 0;

      baselineSpend += bCost;
      tokenistSpend += tCost;
      optimizerSpend += optCost;
      savingsList.push(savings);

      const decision = r.economics?.optimizationDecision;
      if (decision === 'OPTIMIZED') {
        optimizedCount++;
      } else if (decision === 'BASELINE' || decision === 'ABSTAINED') {
        abstainedCount++;
      }

      if (r.isEconomicallyEffective) {
        effectiveCount++;
      }

      if (r.economics?.actual?.optimized.retryCost && r.economics.actual.optimized.retryCost > 0) {
        retryCount++;
      }
    }

    const netSavings = parseFloat((baselineSpend - tokenistSpend).toFixed(6));
    const savingsPercent = baselineSpend > 0 ? parseFloat(((netSavings / baselineSpend) * 100).toFixed(2)) : 0;
    const averageSavings = parseFloat((netSavings / this.records.length).toFixed(6));

    savingsList.sort((a, b) => a - b);
    const mid = Math.floor(savingsList.length / 2);
    const medianSavings = savingsList.length % 2 !== 0 ? savingsList[mid] : (savingsList[mid - 1] + savingsList[mid]) / 2;

    return {
      baselineSpend: parseFloat(baselineSpend.toFixed(6)),
      tokenistSpend: parseFloat(tokenistSpend.toFixed(6)),
      optimizerSpend: parseFloat(optimizerSpend.toFixed(6)),
      netSavings,
      savingsPercent,
      requestCount: this.records.length,
      optimizedRequestCount: optimizedCount,
      abstainedRequestCount: abstainedCount,
      economicallyEffectiveRate: parseFloat(((effectiveCount / this.records.length) * 100).toFixed(1)),
      averageSavings,
      medianSavings: parseFloat(medianSavings.toFixed(6)),
      retryRate: parseFloat(((retryCount / this.records.length) * 100).toFixed(1)),
    };
  }

  public getRecords(): OptimizationReceipt[] {
    return [...this.records];
  }

  public clear(): void {
    this.records = [];
    this.persistToDisk();
  }

  public setLedgerPath(customPath: string): void {
    this.ledgerPath = customPath;
    this.loadFromDisk();
  }

  private loadFromDisk(): void {
    try {
      if (fs.existsSync(this.ledgerPath)) {
        const raw = fs.readFileSync(this.ledgerPath, 'utf-8');
        this.records = JSON.parse(raw);
      }
    } catch {}
  }

  private persistToDisk(): void {
    try {
      const dir = path.dirname(this.ledgerPath);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }
      fs.writeFileSync(this.ledgerPath, JSON.stringify(this.records, null, 2), 'utf-8');
    } catch {}
  }
}

