/**
 * Classifies a user prompt into a structured TaskProfile using deterministic keyword matching.
 * Requires zero LLM calls, operates in under 1 millisecond.
 */
export function classifyTask(userPrompt: string): TaskProfile {
  if (!userPrompt || userPrompt.trim().length === 0) {
    return {
      taskType: 'unknown',
      complexityScore: 0.5,
      confidence: 0.5,
      detectedKeywords: [],
      recommendedBudgetMultiplier: 1.0,
      minRetentionThreshold: 0.85,
      reasoning: 'Empty prompt provided, using default fallback profile.'
    };
  }

  const matches: Array<{ rule: TaskPatternRule; matchedKeywords: string[]; count: number }> = [];

  for (const rule of TASK_RULES) {
    const matchedKeywords: string[] = [];
    for (const regex of rule.keywords) {
      const match = userPrompt.match(regex);
      if (match) {
        matchedKeywords.push(match[0].toLowerCase());
      }
    }
    if (matchedKeywords.length > 0) {
      matches.push({
        rule,
        matchedKeywords,
        count: matchedKeywords.length
      });
    }
  }

  if (matches.length === 0) {
    return {
      taskType: 'unknown',
      complexityScore: 0.5,
      confidence: 0.5,
      detectedKeywords: [],
      recommendedBudgetMultiplier: 1.0,
      minRetentionThreshold: 0.85,
      reasoning: 'No specific task type keywords matched; defaulted to general task profile.'
    };
  }

  // Sort by highest match count first, then by higher rule complexity score (priority tie-breaker)
  matches.sort((a, b) => {
    if (b.count !== a.count) return b.count - a.count;
    return b.rule.complexityScore - a.rule.complexityScore;
  });
  const bestMatch = matches[0];

  const uniqueKeywords = Array.from(new Set(bestMatch.matchedKeywords));
  let confidence = 0.75;
  if (uniqueKeywords.length >= 3) {
    confidence = 0.95;
  } else if (uniqueKeywords.length === 2) {
    confidence = 0.85;
  }

  return {
    taskType: bestMatch.rule.taskType,
    complexityScore: bestMatch.rule.complexityScore,
    confidence,
    detectedKeywords: uniqueKeywords,
    recommendedBudgetMultiplier: bestMatch.rule.recommendedBudgetMultiplier,
    minRetentionThreshold: bestMatch.rule.minRetentionThreshold,
    reasoning: `Matched ${bestMatch.rule.taskType} profile based on keywords: [${uniqueKeywords.join(', ')}]. ${bestMatch.rule.description}`
  };
}

export interface Message {
  role: 'user' | 'assistant' | 'system';
  content: string;
}

/**
 * Prunes conversational history to minimize tokens in multi-turn conversations.
 * @param messages Array of history messages.
 * @param maxTurns Maximum turns (pairs of user/assistant messages) to keep fully intact (default: 5).
 */
export function pruneHistory(messages: Message[], maxTurns = 5): Message[] {
  if (messages.length === 0) return [];

  const pruned: Message[] = [];
  const nonSystemMessages = messages.filter((m) => m.role !== 'system');
  const keepCount = maxTurns * 2;
  const cutoffIndex = nonSystemMessages.length - keepCount;

  // Track how many non-system messages we've processed
  let nonSystemCount = 0;

  for (const msg of messages) {
    if (msg.role === 'system') {
      pruned.push(msg);
      continue;
    }

    const isProtected = nonSystemCount >= cutoffIndex;
    nonSystemCount++;

    if (isProtected) {
      // Keep recent turns fully intact
      pruned.push(msg);
    } else {
      // Apply pruning filters to older turns
      const prunedContent = cleanContent(msg.content);
      if (prunedContent.trim().length > 0) {
        pruned.push({
          role: msg.role,
          content: prunedContent,
        });
      }
    }
  }

  return pruned;
}

/**
 * Filter out repetitive debug/crash traces or collapse stack traces.
 */
function cleanContent(content: string): string {
  // Regex to match typical stack trace blocks
  // e.g. "Error: ... \n    at ... \n    at ..."
  const stackTraceRegex = /(Error: [^\n]+)\n(?:\s+at [^\n]+\n?)+/g;

  let cleaned = content;

  // Replace stack traces with collapsed placeholder
  cleaned = cleaned.replace(stackTraceRegex, '$1\n[Stack trace collapsed]');

  // Drop terminal dumps if they are very long and contain repetitive warnings/errors
  const isTerminalDump =
    (cleaned.includes('npm ERR!') ||
      cleaned.includes('node:internal') ||
      cleaned.includes('CategoryInfo') ||
      cleaned.includes('FullyQualifiedErrorId')) &&
    cleaned.length > 300;

  if (isTerminalDump) {
    return '[Long terminal build/debug dump removed to save context tokens]';
  }

  return cleaned;
}

import * as path from 'path';

export interface FileData {
  filePath: string; // E.g., 'src/core/guardrails.ts'
  signatures: string; // The AST compressed signatures
  rawCode: string; // The actual full raw code
}

export interface RouteResult {
  filePath: string;
  content: string;
  swapped: boolean; // True if raw code was swapped in
  isDependency?: boolean; // True if it is a 1-hop dependency signature
}

/**
 * Dynamic Data Swapping Matrix
 * Intercepts query and decides which files should expose full raw code versus compressed signatures.
 * Automatically resolves and tags 1-hop dependency signatures when a target is selected for edits.
 * 
 * @param query The user's query/prompt instructions.
 * @param files Collection of files in context with their signatures and raw content.
 * @param getDependencies Optional helper to fetch dependency paths of a given file path.
 */
export function routePrompt(
  query: string,
  files: FileData[],
  getDependencies?: (filePath: string) => string[]
): RouteResult[] {
  const lowercaseQuery = query.toLowerCase();

  // Action keywords suggesting write/update intents
  const actionKeywords = ['edit', 'write', 'update', 'modify', 'change', 'patch', 'replace', 'fix', 'implement'];

  const hasUpdateIntent = actionKeywords.some((keyword) => lowercaseQuery.includes(keyword));

  // Determine targeted files by checking if the query references the file name/path
  const targetFiles = new Set<string>();
  const dependencyFiles = new Set<string>();

  if (hasUpdateIntent) {
    for (const file of files) {
      const baseName = path.basename(file.filePath).toLowerCase();
      const relativePath = file.filePath.toLowerCase();

      // Check if user query mentions either the relative path or the base name of the file
      if (lowercaseQuery.includes(relativePath) || lowercaseQuery.includes(baseName)) {
        targetFiles.add(file.filePath);

        // Fetch dependencies if helper is provided
        if (getDependencies) {
          const deps = getDependencies(file.filePath);
          for (const dep of deps) {
            if (path.resolve(dep) !== path.resolve(file.filePath)) {
              dependencyFiles.add(path.resolve(dep));
            }
          }
        }
      }
    }
  }

  // Map each file to its output content
  return files.map((file) => {
    const isTarget = targetFiles.has(file.filePath);

    // Check if the current file resolves to any path in the dependencyFiles set
    const isDependency = !isTarget && Array.from(dependencyFiles).some(dep => 
      path.resolve(dep) === path.resolve(file.filePath)
    );

    return {
      filePath: file.filePath,
      content: isTarget ? file.rawCode : file.signatures,
      swapped: isTarget,
      isDependency: isDependency
    };
  });
}

import { TenantContext, WorkspaceConfig } from '../types';

/**
 * Resolves the tenant context for the current execution session.
 * For local desktop / developer CLI runs, returns a default local context.
 */
export function resolveTenantContext(
  config?: Partial<WorkspaceConfig>,
  workspaceRoot?: string
): TenantContext {
  const tenantId = config?.tenantId || process.env.SHANAXON_TENANT_ID || 'local';
  const organizationId = config?.organizationId || process.env.SHANAXON_ORG_ID || 'default';
  const workspaceId = config?.workspaces?.[0] || workspaceRoot || process.cwd();

  return {
    tenantId,
    organizationId,
    workspaceId
  };
}

/**
 * Prefixes a cache or memory key with tenant isolation boundaries.
 * For default local single-user execution, returns the raw key un-modified
 * to guarantee total backward compatibility with existing cache files.
 */
export function scopedKey(rawKey: string, tenant: TenantContext): string {
  if (tenant.tenantId === 'local' && tenant.organizationId === 'default') {
    return rawKey;
  }
  return `tenant:${tenant.tenantId}:org:${tenant.organizationId}:${rawKey}`;
}

